// ═══ ROADSIDE FIRE
class _RoadFireStrip{
  constructor(w,h){
    this.w=w;this.h=h;
    this.heat=new Uint8Array(w*h);
    this.img=null;                                // lazily sized to the real canvas
    this.pal=[];
    for(let i=0;i<256;i++){
      let r,g,b;
      if(i<64){r=i*4;g=0;b=0;}
      else if(i<128){r=255;g=(i-64)*4;b=0;}
      else if(i<192){r=255;g=255;b=(i-128)*4;}
      else{r=g=b=255;}
      this.pal.push([r,g,b]);
    }
    for(let x=0;x<w;x++)this.heat[(h-1)*w+x]=255;   // seed the base row
  }
  step(){
    const w=this.w,h=this.h,f=this.heat;
    for(let y=1;y<h;y++)for(let x=0;x<w;x++){
      const src=y*w+x;
      const decay=(Math.random()*3)|0;
      const wind=((Math.random()*3)|0)-1;
      const dst=src-decay+wind-w;
      if(dst>=0&&dst<f.length)f[dst]=Math.max(0,f[src]-decay);
    }
    for(let x=0;x<w;x++)f[(h-1)*w+x]=Math.max(120,255-((Math.random()*40)|0));
  }
}
