const DRAFT_Z      = 9.0;     // segments of reach behind the lead machine
const DRAFT_X      = 0.40;    // lateral half-width of the tow

function draftFactor(me,others){
  if(!me||!others)return 1;
  var best=0;
  for(var i=0;i<others.length;i++){
    var o=others[i]; if(!o||o===me)continue;
    var dz=(o.z||0)-(me.z||0);
    if(dz<=0)continue;                       // only a machine AHEAD tows
    var fz=1-(dz/(SEG_LEN*DRAFT_Z));
    if(fz<=0)continue;
    var fx=1-(Math.abs((o.x||0)-(me.x||0))/DRAFT_X);
    if(fx<=0)continue;
    /* Squared falloff on distance, so the tow is concentrated close behind
       rather than spread thinly across the whole reach. */
    var f=fz*fz*fx;
    if(f>best)best=f;
  }
  return 1+(DRAFT_MAX-1)*Math.min(1,best);
}
