// Asymmetric jump arc: sine lift with a compressed descent phase.
function airLift(start,now){
  const el=now-start;
  if(el<=0)return 0;
  let p;
  if(el<=AIR_UP)p=(el/AIR_UP)*0.5;
  else p=0.5+((el-AIR_UP)/AIR_DOWN)*0.5;
  if(p>=1)return 0;
  return Math.sin(Math.PI*p);
}
