// Structural templates: word order per slot. A healthy mix of classic
// three-word arcade names, punchy two-worders, and colourful variants.
const nameTemplates=[
  ['environment','feature','classification'],
  ['modifier','environment','classification'],
  ['modifier','feature','classification'],
  ['environment','classification'],
  ['environment','feature'],
  ['color','environment','classification'],
  ['adjective','feature','classification'],
  ['adjective','color','environment'],
  ['color','feature'],
  ['modifier','classification'],
];
// Short fallback templates guaranteed to fit the 26-char cap.
const shortTemplates=[['environment','classification'],['color','feature'],['modifier','classification']];
const NAME_MAX=26;

function _bankWords(bank,biome){
  const arr=wordBanks[bank];
  if(bank!=='environment')return arr;
  // Biome filtering: keep entries whose tags include the biome; if the filter
  // would empty the pool (unknown biome) fall back to all environments.
  const src=biome?arr.filter(e=>e.tags&&e.tags.includes(biome)):arr;
  return (src.length?src:arr).map(e=>e.w);
}
// Weighted pick with alliteration boost:
// Otherwise (or when no match exists) pick uniformly from unused words.
function _pickWord(cands,used,firstLetter,rng){
  const free=cands.filter(w=>!used.has(w));          // deduplication guard
  if(!free.length)return null;
  if(firstLetter&&rng()<0.25){
    const allit=free.filter(w=>w[0]===firstLetter);
    if(allit.length)return allit[~~(rng()*allit.length)];
  }
  return free[~~(rng()*free.length)];
}
function _buildName(tpl,biome,rng){
  const used=new Set();
  const parts=[];
  let firstLetter=null;
  for(const slot of tpl){
    const w=_pickWord(_bankWords(slot,biome),used,firstLetter,rng);
    if(!w)return null;
    used.add(w);
    if(!firstLetter)firstLetter=w[0];
    // The Prefix Rule: environments get a 10% chance of a location prefix
    // ("Ridge Speedway" → "Upper Ridge Speedway").
    if(slot==='environment'&&rng()<0.10){
      const pf=_pickWord(wordBanks.prefix,used,null,rng);
      if(pf){used.add(pf);parts.push(pf);}
    }
    parts.push(w);
  }
  return parts.join(' ');
}
function generateTrackName(biome,rng){
  rng=rng||Math.random;
// Length cap: reroll up to 8 times; each failed attempt may pick a new template.
  for(let attempt=0;attempt<8;attempt++){
    const tpl=nameTemplates[~~(rng()*nameTemplates.length)];
    const nm=_buildName(tpl,biome,rng);
    if(nm&&nm.length<=NAME_MAX)return nm;
  }
  for(let attempt=0;attempt<12;attempt++){
    const tpl=shortTemplates[~~(rng()*shortTemplates.length)];
    const nm=_buildName(tpl,biome,rng);
    if(nm&&nm.length<=NAME_MAX)return nm;
  }
  return 'Apex Circuit';                              // absolute fallback
}
// Deterministic mapping table: seed → name (memoised). The same magic car /
// saved track therefore always resolves to the same name.
const TRACK_NAME_CACHE={};
function trackNameForSeed(seed,biome){
  const key=(seed>>>0)+'|'+(biome||'');
  if(TRACK_NAME_CACHE[key])return TRACK_NAME_CACHE[key];
  const nm=generateTrackName(biome,rngFactory((seed^0x51ed1e55)>>>0));
  TRACK_NAME_CACHE[key]=nm;
  return nm;
}
window.TrackNames={generate:generateTrackName,forSeed:trackNameForSeed,banks:wordBanks};

