// ── PROCEDURAL THEME EXPANSION
// hue) so it always looks intentional, never random noise.
TRACK_THEMES.forEach((t,i)=>{ if((i*13+7)%100<18) t.lensFlare=0.4+((i*37)%40)/100; });
(function(){
  const hx=(h,s2,l)=>{ // hsl→hex
    h=((h%360)+360)%360; s2/=100; l/=100;
    const c=(1-Math.abs(2*l-1))*s2, x=c*(1-Math.abs((h/60)%2-1)), m=l-c/2;
    let r,g,b;
    if(h<60){r=c;g=x;b=0;}else if(h<120){r=x;g=c;b=0;}
    else if(h<180){r=0;g=c;b=x;}else if(h<240){r=0;g=x;b=c;}
    else if(h<300){r=x;g=0;b=c;}else{r=c;g=0;b=x;}
    const to=(v)=>('0'+Math.round((v+m)*255).toString(16)).slice(-2);
    return '#'+to(r)+to(g)+to(b);
  };
  const target=128;
  const need=target-TRACK_THEMES.length;
  const suffixes=['NEXUS','PRIME','FLUX','VEIL','SPIRE','DRIFT','ECHO','PULSE',
    'HALO','VORTEX','RIFT','GLOW','WAVE','ZONE','CORE','EDGE','MIST','BLAZE',
    'FROST','STORM','DUSK','DAWN','RUSH','ARC','NOVA',' EMBER','TIDE','GALE',
    'BLOOM','SHADE'];
  const roots=['AZURE','VERDANT','CRIMSON','AMBER','VIOLET','TEAL','MAGENTA',
    'COBALT','JADE','SCARLET','INDIGO','LIME','CORAL','SLATE','ROSE','CYAN',
    'GOLD','PLUM','MINT','RUBY','STEEL','SAGE','ONYX','PEARL'];
  for(let n=0;n<need;n++){
    const baseH=(n*137.508)%360;        // golden-angle hue spread
    const night=(n%3)!==0;              // 2/3 night, 1/3 day
    const accentH=(baseH+150)%360;      // complementary-ish accent
    const railH2=(baseH+40)%360;
    const skyL=night?[6,12,20]:[52,64,78];
    const roadL=night?[14,20]:[30,40];
    const floorL=night?[10,16]:[34,44];
    const nm=roots[n%roots.length]+' '+suffixes[(n*7+3)%suffixes.length];
    TRACK_THEMES.push({
      name:nm,
      skyA:hx(baseH,night?60:45,skyL[0]),
      skyB:hx(baseH,night?70:55,skyL[1]),
      skyC:hx(baseH,night?80:65,skyL[2]),
      roadA:hx(baseH,20,roadL[0]),
      roadB:hx(baseH,24,roadL[1]),
      railL:hx(accentH,90,60),
      railR:hx(railH2,85,58),
      floorA:hx(baseH,25,floorL[0]),
      floorB:hx(baseH,30,floorL[1]),
      bldgHues:[Math.round(baseH),Math.round((baseH+20)%360),Math.round((baseH+340)%360)],
      bldgPal:[hx(baseH,20,night?18:40),hx(baseH,25,night?26:50),hx(baseH,15,night?12:32)],
      bldgPalH:[hx(accentH,70,night?55:65),hx(railH2,65,night?50:60),hx(accentH,80,night?60:70)],
      urban:(n%2)===0, vegHue:Math.round((baseH+90)%360),
      rain:((n*13)%100)/300, clouds:0.15+((n*29)%70)/100,
      daylight:!night
    });
  }
})();

