const CHAR_NAMES=['sweeper','technical','speedway','alpine','labyrinth','rollercoaster',
                  'gauntlet','drift','canyon','sprint','marathon','chaos'];
function charForSeed(seed){
  // Must match the draw in buildTrack exactly, or theme and geometry disagree.
  const r2=rngFactory((seed>>>0)||1);
  for(let i=0;i<3;i++)r2();          // same position in the stream
  return CHAR_NAMES[~~(r2()*12)];
}
/* ═══ PALETTE ↔ BIOME AFFINITY (plan item 24)
   The biome (weather, flora, landscape) and the named palette were drawn
   independently: seed % 144 picked the palette, the theme RNG picked the
   biome. So a glacier got INFERNO CORE, a jungle got LAVA, a desert got
   DEEP SEA DRIFT — the scenery said one place and the colours another.
   Each biome already declares its natural sky and floor hues (BIOME_DEFS).
   Every palette is scored against them — hue distance of its floor and sky,
   plus lightness rules for snow and volcanic biomes — and the seed picks
   among the twelve best matches, so every biome keeps plenty of variety but
   never a contradiction. Cached per biome; deterministic per seed. */
function _hexHSL(hex){
  const h=String(hex||'#000').replace('#','');
  const r=parseInt(h.slice(0,2),16)/255||0, g=parseInt(h.slice(2,4),16)/255||0, b=parseInt(h.slice(4,6),16)/255||0;
  const mx=Math.max(r,g,b), mn=Math.min(r,g,b), l=(mx+mn)/2, d=mx-mn;
  if(d<1e-6)return [0,0,l];
  const sat=l>0.5?d/(2-mx-mn):d/(mx+mn);
  let hue=mx===r?((g-b)/d+(g<b?6:0)):mx===g?((b-r)/d+2):((r-g)/d+4);
  return [hue*60,sat,l];
}
const _themePools={};
function _themeForBiome(seed,biome){
  const B=BIOME_DEFS[biome];
  if(!B)return TRACK_THEMES[((seed>>>0)%TRACK_THEMES.length+TRACK_THEMES.length)%TRACK_THEMES.length];
  let pool=_themePools[biome];
  if(!pool){
    const hd=(a,b)=>{ const d=Math.abs(((a-b)%360+540)%360-180); return d; };
    const snow=B.tag==='snow', hot=(biome==='volcano'), urban=(B.tag==='city');
    const scored=TRACK_THEMES.map((T,i)=>{
      const f=_hexHSL(T.floorA), k=_hexHSL(T.skyC||T.skyB);
      // A grey floor or sky has no meaningful hue: score it as a middling match.
      const fd=f[1]<0.12?70:hd(f[0],B.floor), kd=k[1]<0.12?70:hd(k[0],B.sky);
      let sc=fd*1.0+kd*0.6;
      if(snow&&f[2]<0.30&&!T.daylight)sc+=40;             // snow country is not a black floor
      if(snow&&f[1]>0.25&&hd(f[0],30)<40)sc+=80;           // …nor an orange one
      if(hot&&f[2]>0.45)sc+=50;                            // volcanic ground is dark
      if(urban&&T.urban)sc-=25;
      if(!urban&&biome!=='lunar'&&T.urban&&f[1]>0.4&&fd>60)sc+=20;
      return {i,sc};
    }).sort((a,b)=>a.sc-b.sc||a.i-b.i);
    pool=_themePools[biome]=scored.slice(0,12).map(o=>TRACK_THEMES[o.i]);
  }
  let h=Math.imul((seed>>>0)^0x5bd1e995,0x9e3779b1)>>>0; h=(h^(h>>>15))>>>0;
  return pool[h%pool.length];
}
/* ═══ THEME OVERRIDES THAT WERE NEVER READ
   Super Racing's BIOME and WEATHER selectors wrote _forceBiome / _rainOdds /
   _snowOdds / _sandOdds, and several presets wrote _forceNight, _snowClass and
   _stormForce — but nothing read any of them, so those controls did nothing.
   makeTheme now honours them (and _forceTheme, a palette by name), which is
   also how World Tour signatures give a municipality its look. Forced values
   are applied after the theme's own draws, so the stream — and everything
   else about the seed — is unchanged. */
function makeTheme(seed){
  const th=_makeThemeImpl(seed);
  const o=(typeof dm!=='undefined'&&dm&&dm._algoOverride)||null;
  if(!o)return th;
  const hf=(k)=>{ let h=Math.imul(((seed>>>0)^k)>>>0,0x9e3779b1)>>>0; h=(h^(h>>>15))>>>0; return h/4294967296; };
  if(o._rainOdds!=null){ th.rain=hf(0x11)<+o._rainOdds; if(th.rain)th.wet=true; }
  if(o._snowOdds!=null)th.snow=hf(0x22)<+o._snowOdds;
  if(o._sandOdds!=null)th.sandForce=hf(0x33)<+o._sandOdds;
  if(typeof o._snowClass==='string')th.snowClass=o._snowClass;
  if(o._stormForce!=null&&isFinite(+o._stormForce))th.storm=Math.max(0,Math.min(1,+o._stormForce));
  if(o._forceNight){ th.forceNight=true; th.timeT=0.93; dm._dayLock=null; }
  return th;
}
function _makeThemeImpl(seed){
  let _hfTmp=null;   // shared between the heavyFog and timeT fields below
  const r=rngFactory(seed*2654435761>>>0);
  const _CH=CHAR_LOOK[charForSeed(seed)]||CHAR_LOOK.sweeper;
  // pick a biome: 30% chance to mirror the current battle biome
  let biome=BIOME_LIST[~~(r()*BIOME_LIST.length)];
  try{
    if(r()<0.30&&typeof CFG!=='undefined'&&CFG&&CFG._chosenBiome&&BIOME_DEFS[CFG._chosenBiome])
      biome=CFG._chosenBiome;
  }catch(e){}
  {
    const _fo=(typeof dm!=='undefined'&&dm&&dm._algoOverride)||null;
    if(_fo&&typeof _fo._forceBiome==='string'&&BIOME_DEFS[_fo._forceBiome])biome=_fo._forceBiome;
  }
  const B=BIOME_DEFS[biome];
  // Pick a track theme (every seed gets one; biome drives weather/particles)
  const _ftName=(typeof dm!=='undefined'&&dm&&dm._algoOverride&&dm._algoOverride._forceTheme)||null;
  const TT=(_ftName&&TRACK_THEMES.find(t=>t.name===_ftName))||_themeForBiome(seed,biome)||TRACK_THEMES[0];
  // Lock daylight themes to a daytime clock so shading agrees with the sky.
  if(TT.daylight&&dm.todOverride==null)dm._dayLock=0.34+((seed>>>7)%100)/100*0.28;
  else dm._dayLock=null;
  // Rough hue approximation from theme sky hex for palette helpers
  const baseHue=(parseInt(TT.skyC.slice(1,3),16)/255*60+parseInt(TT.skyC.slice(5,7),16)/255*240)|0;
  const floorHue=(parseInt(TT.floorA.slice(3,5),16)>parseInt(TT.floorA.slice(5,7),16)?120:
    parseInt(TT.floorA.slice(1,3),16)>parseInt(TT.floorA.slice(5,7),16)?20:200);
  return{
    seed,
    skyHue:baseHue,
    planet: (TT.name==='BLOOD MOON'||TT.name==='MIDNIGHT CITY'||TT.name==='VOLCANIC ASH')
      ?{hue:(baseHue+180+~~(r()*60))%360,ring:r()<0.4,x:0.65+r()*0.20,y:0.10+r()*0.10,r:0.07+r()*0.05}:null,
    twinPlanet:r()<0.25,
    floorHueA:floorHue, floorHueB:(floorHue+26)%360,
    vivid:true,
    floorSat:30+~~(r()*20), floorLumA:12+~~(r()*10), floorLumB:18+~~(r()*10),
    depthTier:1+~~(r()*3),
    skyDrift:0.3+r()*1.5,
    trackTheme:TT,                          // full named theme object
    bldgHues:[(floorHue+180)%360,(floorHue+210)%360,(floorHue+150)%360],
    railL:TT.railL,
    railR:TT.railR,
    roadA:TT.roadA,
    roadB:TT.roadB,
    starDensity:60+~~(r()*70),
    cityLine:r()<0.85,
    /* 20 ground texture styles, selected by biome for visual variety.
       Each style draws different patterns on the scenery ground. */
    sideStyle:(function(){
      const roll=r();
      if(biome==='lunar')return ['grid','circuit','hexGrid','moire','darkPlain'][~~(roll*5)];
      if(biome==='canyon')return ['dirt','sandstone','rockBed','circuit'][~~(roll*4)];
      if(biome==='desert')return ['dirt','sandstone','crackedEarth','dusty','grid'][~~(roll*5)];
      if(biome==='forest')return ['grass','mossy','leafLitter','fern','dirt'][~~(roll*5)];
      if(biome==='alpine')return ['grass','snow','gravel','rockBed','mossy'][~~(roll*5)];
      if(biome==='tropical')return ['grass','lush','mossy','muddy','leafLitter'][~~(roll*5)];
      if(biome==='tundra')return ['snow','gravel','darkPlain','dirt'][~~(roll*4)];
      if(biome==='volcanic')return ['darkPlain','rockBed','crackedEarth','circuit'][~~(roll*4)];
      /* Urban/default biomes */
      return ['grid','tiles','hexGrid','circuit','concrete','moire',
              'grass','dirt','asphalt','cobble','darkPlain'][~~(roll*11)];
    })(),
    clouds:r()<B.clouds,                    // biome-weighted cloud odds
    rain:r()<B.rain,                        // biome-weighted rain odds
    parallax:r()<0.30?(2+~~(r()*7)):1,      // 2–8× background parallax depth
    cityBack:r()<0.30,                      // distant street-level city skyline
    hilly:r()<0.5,                          // rolling elevation profile
    // Nebula: only space/night themes
    nebula: (biome==='lunar'||TT.name==='MIDNIGHT CITY'||TT.name==='NEON TOKYO'||TT.name==='BLOOD MOON'),
    // Aurora: only cold-biome tracks at night
    // biome, so on a random night track it essentially never appeared. Any
    auroraHue:(function(){
      var band=r();
      if(band<0.34)return 105+~~(r()*45);        // oxygen green, the classic
      if(band<0.52)return 285+~~(r()*40);        // nitrogen violet
      if(band<0.66)return 320+~~(r()*35);        // magenta mixtures
      if(band<0.78)return 350+~~(r()*20);        // high-altitude oxygen red
      if(band<0.88)return 195+~~(r()*35);        // nitrogen blue
      if(band<0.95)return 165+~~(r()*25);        // rare teal
      return (baseHue+150+~~(r()*90))%360;       // tied to the track's own sky
    })(),
// (2) Per-track curtain palette spread, layout and vertical extent.
    auroraSpread:(18+~~(r()*120)),
      /* Fold pattern rolled independently of colour, so motion and palette vary separately instead of moving in lockstep. */
    auroraShape:~~(r()*8),
      /* (3) SKY PHENOMENA. Twelve atmospheric effects beyond the aurora, rolled independently so they can co-occur the way a real sky does, with odds tuned so a track carries one or two rather than a pile-up. */
    skyFx:(function(){
      return {
        airglow:r()<0.22, pillars:r()<0.10, zodiacal:r()<0.09,
        noctilucent:r()<0.08,
        gegenschein:r()<0.05, volcanic:r()<0.07, sprites:r()<0.06,

        hue:~~(r()*360), phase:r()*6.283
      };
    })(),
    auroraPlace :(0.05+r()*0.30),         // where the first curtain sits
    auroraStep  :(0.14+r()*0.34),         // spacing between curtains
    auroraHi    :(0.02+r()*0.10),         // top of the display
    auroraLo    :(0.45+r()*0.45),         // how far down it reaches
    aurora: (biome==='arctic'||biome==='tundra'||TT.name==='ICE REALM'
             ||TT.name==='ARCTIC STORM'||r()<0.22),
    // Sun/moon disc: always visible during day, but not in space themes
    disc: !(biome==='lunar'||TT.name==='MIDNIGHT CITY'),
    fogTint:[(baseHue+300)%360,(baseHue+180)%360,(baseHue+60)%360][~~(r()*3)],
    // (5) STORM INTENSITY, 0..1. Most wet tracks stay light; roughly a third
    wet:(r()<0.28),
    snow:(function(){
      // Keyed off the theme name and biome only — both are in scope here;
      // the scene profile is chosen later in buildTrack and is not.
      const cold=/GLACIER|FROST|TUNDRA|ALPINE|ICE|POLAR|WINTER|SNOW/.test(String(TT.name||''))
              || biome==='tundra' || biome==='lunar';
      return cold?(r()<0.75):(r()<0.10);
    })(),
      /* (1) WINTER TRACKS. The GPU handles far more particles than the density roll was asking for, so a distinct class of track now goes well beyond normal snowfall: 12% of snowy tracks are full whiteouts. */
    snowClass:(function(){
      var q=r();
      return q<0.12?'whiteout' : q<0.34?'heavy' : q<0.70?'normal' : 'light';
    })(),
    storm:(function(){
      const q=r();
      return q<0.22?0 : q<0.55?(0.45+r()*0.25) : (0.80+r()*0.20);
    })(),
    // (5) Lens flare is no longer a rare flag — bright daylight tracks get a
    // strong one, so clear weather is as distinctive as foul weather.
    lensFlare:(r()<0.62?(0.80+r()*0.70):0),
    geoTheme:(function(){
      if(r()>=_AO('_geoTrackOdds',0.04))return null;
      const shapes=['hexPrism','stepPyramid','torusGate','octoSpire','cubeStack','archRibs'];
      const fills =['gradient','banded','checker','scanline','facetShade','dither'];
      const pick=(a,n)=>{const o=[];const p2=a.slice();
        for(let i=0;i<n&&p2.length;i++)o.push(p2.splice(~~(r()*p2.length),1)[0]);return o;};
      return {
        shapes:pick(shapes,2+~~(r()*3)),
        fill:fills[~~(r()*fills.length)],
        // A deliberate multi-hue palette, not one colour on repeat — this is
        // the other half of (13): "a wide range of colours that fit the scene".
        palette:[0,32,68,150,210,285].map(off=>(baseHue+off+~~(r()*18))%360),
        accent:(baseHue+180)%360,
        density:0.6+r()*0.8
      };
    })(),
    // (8)(17)(20) How hard palette and scenery shift along the lap.
    sceneryVariety:_AO('_sceneryVariety',1.0)*(0.6+r()*0.9),
    // ── SCENERY ZONES — the lap becomes a JOURNEY, not a loop
    zones:(function(){
      const count=3+~~(r()*4);                    // 3-6 zones per lap
      const backdrops=['alpine','mesa','crystal','plateau','volcano',
                       'pyramids','city','arcology','forest','monoliths','dunes'];
      const dir=r()<0.5?-1:1;
      const out=[];
      let h=(_CH.h+(r()*_CH.sp-_CH.sp/2)+360)%360;
        /* (19) COLOUR VARIETY BIAS. A small extra share of tracks is pulled toward white, yellow or turquoise — palettes the character families rarely reach on their own, and which pair well with the newer effects (pale scenery  */
      var _cbRoll=r();
      var _cbSat=null, _cbLum=null;
      if(_cbRoll<0.02){        // white: near-zero saturation, high brightness
        h=(h+r()*30)%360; _cbSat=6+~~(r()*10); _cbLum=58+~~(r()*16);
      } else if(_cbRoll<0.04){ // yellow
        h=44+~~(r()*16);  _cbSat=64+~~(r()*28); _cbLum=48+~~(r()*18);
      } else if(_cbRoll<0.06){ // turquoise
        h=168+~~(r()*22); _cbSat=58+~~(r()*30); _cbLum=44+~~(r()*20);
      }
      // Backdrops drawn without replacement, so a 4-zone lap can never be
      const pool=(_CH.b||[]).concat(backdrops.filter(x=>(_CH.b||[]).indexOf(x)<0));
      for(let i=0;i<count;i++){
        const bd=pool.length?pool.splice(~~(r()*pool.length),1)[0]
                            :backdrops[~~(r()*backdrops.length)];
        out.push({
          at:i/count,                             // start position around the lap
          hue:((h%360)+360)%360,
          sat:(_cbSat!=null)?_cbSat:Math.max(8,Math.min(96,_CH.s+~~(r()*36)-18)),
          // Brightness likewise: a labyrinth is committed to being dark and a
          // speedway to being bright, with variation inside that commitment.
          lumA:(_cbLum!=null)?_cbLum:Math.max(5,Math.min(76,_CH.l+~~(r()*26)-13)),
          lumB:0,                               // filled below, relative to A
          backdrop:bd,
          vegDens:Math.max(0,Math.min(1,_CH.v+r()*0.4-0.2)),   // (1) per character
          vegHue:((h+120+~~(r()*80))%360+360)%360,
          propMix:r(),                            // 0 natural -> 1 built
          skyShift:~~(r()*40)-20
        });
        const _z=out[out.length-1];
        _z.lumB=Math.min(88,_z.lumA+8+~~(r()*14));
        h+=dir*(28+r()*64);
      }
      return out;
    })(),
    heavyFog:(_hfTmp=(function(){
      // (8) Fog was effectively invisible at 12.5% odds. Tripled, and the
      // reach is tightened so when it appears you actually cannot see far.
      if(r()>=_AO('_fogOdds',0.375))return null;
      const dens=0.55+r()*0.40;                     // 0.55–0.95, genuinely thick
      return {
        density:Math.min(1,dens*_AO('_fogDensity',1.0)),
        // Fog takes its colour from the sky so it reads as the same air.
        hue:(baseHue+(r()<0.5?0:180)+~~(r()*40)-20)%360,
        sat:8+~~(r()*22),                           // fog is desaturated
        lum:r()<0.5?(10+~~(r()*10)):(58+~~(r()*14)),
        reach:(0.28+r()*0.24)*_AO('_fogReach',1.0)
      };
    })()),
    floorPattern:['checker','stripes','diamond'][~~(r()*3)],
    timeT:_hfTmp?(r()<0.34?(0.82+r()*0.15):(0.30+r()*0.34)):(function(){
      const q=r();
      return q<0.44?(0.28+r()*0.34)      // 44% full day    (0.28-0.62)
           : q<0.68?(0.62+r()*0.18)      // 24% golden hour (0.62-0.80)
           : q<0.86?(0.86+r()*0.28)%1    // 18% night       (0.86-0.14)
                   :(0.14+r()*0.14);     // 14% dawn        (0.14-0.28)
    })(),
    biome,                                  // battle-mode biome id
    biomeFx:B.fx,                           // ambient particle effect
    // vegetation palette: green is only one of six moods
    vegHue:(function(){
      const pal=[B.veg,                     // biome green family
        30+~~(r()*25),                      // autumn orange/amber
        330+~~(r()*25),                     // cherry pink
        165+~~(r()*30),                     // teal
        270+~~(r()*30),                     // violet
        55+~~(r()*15)][~~(r()*6)];          // golden
      return (pal+360)%360;})(),
    vegDensity:0.25+r()*0.35,               // fraction of props that are plants
    postLine:r()<0.4,
      /* ═══ THE WHITELIST WAS OVERRIDING THE THEME FLAG  36 of the track themes carry `hasMountains:true` in their own definition. */
    hasMountains: !!(TT.hasMountains
      ||TT.name==='ICE REALM'||TT.name==='CHROME DESERT'||TT.name==='LAVA WORLD'
      ||TT.name==='EMERALD CORE'||TT.name==='ARCTIC STORM'
      ||TT.name==='VOLCANIC ASH'||TT.name==='GOLDEN CIRCUIT'),
    // horizon silhouette style: 0 alpine, 1 mesa, 2 crystal, 3 plateau, 4 volcanic
    mountainStyle:({'ICE REALM':2,'CHROME DESERT':1,'LAVA WORLD':4,'EMERALD CORE':0,
                    'ARCTIC STORM':0,'VOLCANIC ASH':4,'GOLDEN CIRCUIT':3}[TT.name])??~~(r()*5),
  };
}

// ─── TRACK
function addSegment(curve,y){
  const n=segments.length;
  const lastY=n?segments[n-1].p2.world.y:0;
  segments.push({index:n,curve,
    p1:{world:{y:lastY,z:n*SEG_LEN},camera:{},screen:{}},
    p2:{world:{y,z:(n+1)*SEG_LEN},camera:{},screen:{}},
    color:Math.floor(n/RUMBLE_LEN)%2, boost:false, pit:false, sprite:null});
}
function addRoad(enter,hold,leave,curve,hillY){
  const startY=segments.length?segments[segments.length-1].p2.world.y:0;
  const endY=startY+(hillY||0)*SEG_LEN;
  const total=enter+hold+leave;
  const eIn=(a,b,t)=>a+(b-a)*t*t, eOut=(a,b,t)=>a+(b-a)*(1-(1-t)*(1-t));
  const eIO=(a,b,t)=>a+(b-a)*((-Math.cos(t*Math.PI)/2)+0.5);
  for(let n=0;n<enter;n++)addSegment(eIn(0,curve,n/enter),eIO(startY,endY,n/total));
  for(let n=0;n<hold;n++) addSegment(curve,eIO(startY,endY,(enter+n)/total));
  for(let n=0;n<leave;n++)addSegment(eOut(curve,0,n/leave),eIO(startY,endY,(enter+hold+n)/total));
}
// Read an Algorithm-tool override, falling back to the ship default. Every new
// system reads its tuning through this so the tool and the generator can never
const CityLink={
  boostBonus:()=>0, hazardCount:()=>0, gripBonus:()=>0, skylineBoost:()=>0,
  rivalSkill:()=>0, shieldBonus:()=>0, payoutMul:()=>1, _s:()=>null
};
const _zoneCache={t:null,z:-1,v:null};
function zoneAt(z){
  const th=theme;
  if(!th||!th.zones||!th.zones.length)return null;
  const zs=th.zones, n=zs.length;
  const L=(typeof trackLength==='number'&&trackLength>0)?trackLength:1;
  const p=((z/L)%1+1)%1;
  const key=(p*512)|0;
  if(_zoneCache.t===th&&_zoneCache.z===key)return _zoneCache.v;
  const fpos=p*n;
  const i0=Math.floor(fpos)%n, i1=(i0+1)%n;
  let t=fpos-Math.floor(fpos);
  // Smoothstep the blend so zones hold their identity through the middle and
  // transition quickly at the seam, instead of being permanently half-mixed.
  const k=Math.min(1,Math.max(0,(t-0.25)/0.5));
  t=k*k*(3-2*k);
  const a=zs[i0], b=zs[i1];
  const amt=Math.min(1.5,th.sceneryVariety||1);
  const lerpHue=(h1,h2,f)=>{
    let d=((h2-h1)%360+540)%360-180;            // shortest signed path
    return ((h1+d*f)%360+360)%360;
  };
  const mix=(x,y,f)=>x+(y-x)*f;
  const v={
    i:i0, next:i1, blend:t,
    hue:lerpHue(a.hue,b.hue,t),
    sat:mix(a.sat,b.sat,t)*(0.55+0.45*amt),
    lumA:mix(a.lumA,b.lumA,t),
    lumB:mix(a.lumB,b.lumB,t),
    vegDens:mix(a.vegDens,b.vegDens,t),
    vegHue:lerpHue(a.vegHue,b.vegHue,t),
    propMix:mix(a.propMix,b.propMix,t),
    skyShift:mix(a.skyShift,b.skyShift,t)*amt,
    // Backdrops cannot be blended (they are different shapes), so the nearer
    // zone wins and the two overlap in the parallax draw with alpha instead.
    backdrop:t<0.5?a.backdrop:b.backdrop,
    backdropNext:t<0.5?b.backdrop:a.backdrop,
    backdropMix:t<0.5?t*2:(1-t)*2
  };
  _zoneCache.t=th;_zoneCache.z=key;_zoneCache.v=v;
  return v;
}
function _AO(key,dflt){
  const o=(typeof dm!=='undefined'&&dm&&dm._algoOverride)?dm._algoOverride:null;
  if(o&&o[key]!=null)return +o[key];
  /* No feedback steering here any more: see GENERATION NO LONGER BENDS TO
     FEEDBACK. The ship default is the default. */
  return dflt;
}
/* ═══ SCENERY LAYERS — varied, cheap, palette-matched backdrops
   Each layer is painted ONCE per track into an off-screen canvas twice the
   screen width that tiles seamlessly, then drawn every frame with two
   drawImage() calls at its own parallax rate — no per-frame path work and no
   shaders, so the cost is a couple of blits per layer.
   Selection is hashed from the seed (never rng()), so it cannot change a
   track's layout or preview parity. A track gets one FAR layer and, about
   half the time, one MID layer, each drawn evenly from the kinds that suit its
   biome. Colours come from the track's own sky hue and time of day. */
const _SCN_KINDS={
  ridgebands:{tier:'far', biomes:null},
  cloudsea:  {tier:'far', biomes:['alpine','glacier','arctic','tundra','islands','ocean','haunted']},
  mesas:     {tier:'mid', biomes:['desert','canyon','mesa','savanna','volcano','lunar']},
  dunes:     {tier:'mid', biomes:['desert','savanna','mesa','lunar']},
  treeline:  {tier:'mid', biomes:['forest','alpine','swamp','jungle','wetland','haunted','tundra','plains']},
  turbines:  {tier:'mid', biomes:['plains','savanna','ocean','islands','tundra','wetland','arctic']},
  spires:    {tier:'mid', biomes:['neon','lunar','city','volcano','glacier','arctic','haunted']},
  volcanoes: {tier:'far', biomes:['volcano','lunar','jungle','islands','desert']},
  icebergs:  {tier:'far', biomes:['arctic','glacier','tundra','ocean']},
  pylons:    {tier:'mid', biomes:['plains','tundra','savanna','wetland','city','desert']},
  palms:     {tier:'mid', biomes:['islands','ocean','jungle','savanna','desert']},
  deadtrees: {tier:'mid', biomes:['haunted','swamp','wetland','tundra','volcano']},
  domes:     {tier:'mid', biomes:['lunar','neon','city','arctic','desert']},
  monoliths: {tier:'mid', biomes:['desert','lunar','mesa','haunted','canyon','savanna','alpine']}
};
function _scnHash(x){x=(x^0x61c88647)>>>0;x^=x>>>16;x=Math.imul(x,0x7feb352d)>>>0;x^=x>>>15;x=Math.imul(x,0x846ca68b)>>>0;x^=x>>>16;return x>>>0;}
function _scnRand(seed){let s=_mix32(seed>>>0)||1;return function(){s^=s<<13;s>>>=0;s^=s>>>17;s^=s<<5;s>>>=0;return s/4294967296;};}
function sceneryPick(seed,biome){
  const fit=(tier)=>Object.keys(_SCN_KINDS).filter(k=>_SCN_KINDS[k].tier===tier&&(!_SCN_KINDS[k].biomes||_SCN_KINDS[k].biomes.indexOf(biome)>=0));
  const far=fit('far'), mid=fit('mid'), h1=_scnHash((seed>>>0)+0x1234567), h2=_scnHash((seed>>>0)+0x7654321);
  const out=[];
  /* Balance: the generic ridge bands would otherwise be the only far option
     for most biomes and turn up on ~83% of tracks. The far layer is now
     occasional, and every track still gets at least one layer — preferring
     the biome-specific mid layer when the rolls give nothing. */
  /* Up to three layers: one far, and up to two DIFFERENT mid layers. */
  const h3=_scnHash((seed>>>0)+0x2468ace);
  const wantFar=(h1>>>12)%100<75, wantMid=(h2%100)<92, wantMid2=(h3%100)<75;
  if(wantFar&&far.length)out.push(far[h1%far.length]);
  if(wantMid&&mid.length){
    const a=mid[(h2>>>8)%mid.length]; out.push(a);
    if(wantMid2&&mid.length>1){ const rest=mid.filter(k=>k!==a); out.push(rest[(h3>>>8)%rest.length]); }
  }
  if(!out.length){ if(mid.length)out.push(mid[(h2>>>8)%mid.length]); else if(far.length)out.push(far[h1%far.length]); }
  return out;
}
/* Paint one tileable layer. W = tile width, H = height above the horizon. */
function _scnPaint(kind,W,H,seed,hue,night){
  const cv=document.createElement('canvas'); cv.width=W; cv.height=H;
  const c=cv.getContext('2d'); if(!c)return null;
  const R=_scnRand(_scnHash(seed^kind.length*0x9e3779b9));
  const hsla=(h,s,l,a)=>'hsla('+(((h%360)+360)%360).toFixed(0)+','+s+'%,'+l+'%,'+a+')';
  // Draw a shape at x and at its wrapped copies so the tile has no seam.
  const wrap=(x,wid,fn)=>{fn(x); if(x-wid<0)fn(x+W); if(x+wid>W)fn(x-W);};
  const L=night?0:1;               // lightness switch
  if(kind==='ridgebands'){
    const bands=3+Math.floor(R()*2);
    for(let b=0;b<bands;b++){
      const t=b/(bands-1), base=H*(0.55+t*0.35), amp=H*(0.10+0.16*(1-t));
      const f1=1+Math.floor(R()*3), f2=3+Math.floor(R()*4), p1=R()*6.28, p2=R()*6.28;
      c.fillStyle=hsla(hue+10*t, 18+8*t, night?(6+t*4):(52-t*18), 0.55+0.35*t);
      c.beginPath(); c.moveTo(0,H);
      for(let x=0;x<=W;x+=8){
        const y=base-amp*(0.6*Math.sin(x/W*6.2832*f1+p1)+0.4*Math.sin(x/W*6.2832*f2+p2)+1)*0.5;
        c.lineTo(x,y);
      }
      c.lineTo(W,H); c.closePath(); c.fill();
    }
  } else if(kind==='cloudsea'){
    for(let row=0;row<3;row++){
      const t=row/2, top=H*(0.50+t*0.16);
      const g=c.createLinearGradient(0,top-H*0.12,0,H);
      g.addColorStop(0,hsla(hue,night?12:18,night?(22-t*6):(94-t*8),0.9-t*0.2));
      g.addColorStop(1,hsla(hue,night?10:14,night?(10-t*3):(76-t*10),0.95));
      c.fillStyle=g; c.beginPath();
      const n=14+Math.floor(R()*8);
      for(let i=0;i<n;i++){
        const x=R()*W, r=H*(0.10+R()*0.16)*(1-t*0.25), cy=top+r*(0.25+R()*0.35);
        wrap(x,r,(xx)=>{c.moveTo(xx+r,cy); c.arc(xx,cy,r,0,Math.PI*2);});
      }
      c.rect(0,top,W,H-top); c.fill();
    }
  } else if(kind==='mesas'){
    for(let row=0;row<2;row++){
      const near=row===1, n=near?5:8;
      for(let i=0;i<n;i++){
        const x=R()*W, w=W*(near?0.06:0.04)*(0.6+R()*0.8), h=H*(near?0.80:0.55)*(0.55+R()*0.45);
        const slope=w*(0.18+R()*0.2), top=H-h;
        wrap(x,w+slope,(xx)=>{
          c.fillStyle=hsla(hue+(near?-12:4), near?42:30, night?(near?11:17):(near?30:48), near?0.97:0.8);
          c.beginPath(); c.moveTo(xx-w-slope,H); c.lineTo(xx-w,top); c.lineTo(xx+w,top); c.lineTo(xx+w+slope,H); c.closePath(); c.fill();
          // rim light along the flat top
          c.fillStyle=hsla(hue+30, 70, night?30:72, night?0.25:0.45);
          c.fillRect(xx-w,top,w*2,Math.max(1,h*0.035));
        });
      }
    }
  } else if(kind==='dunes'){
    for(let b=0;b<3;b++){
      const t=b/2, base=H*(0.62+t*0.2), amp=H*(0.10+0.06*(1-t)), f=2+b+Math.floor(R()*2), p=R()*6.28;
      const g=c.createLinearGradient(0,base-amp,0,H);
      g.addColorStop(0,hsla(hue+20,night?20:45,night?(14+t*2):(70-t*10),0.85));
      g.addColorStop(1,hsla(hue+10,night?16:38,night?(7):(46-t*10),0.95));
      c.fillStyle=g; c.beginPath(); c.moveTo(0,H);
      for(let x=0;x<=W;x+=6){
        const s=Math.sin(x/W*6.2832*f+p); const y=base-amp*(s>0?Math.pow(s,0.7):s*0.5);
        c.lineTo(x,y);
      }
      c.lineTo(W,H); c.closePath(); c.fill();
    }
  } else if(kind==='treeline'){
    for(let row=0;row<2;row++){
      const near=row===1, count=near?90:130, baseH=H*(near?0.26:0.16);
      c.fillStyle=hsla(hue+(near?-40:-25), near?28:18, night?(near?5:9):(near?20:36), near?0.95:0.65);
      c.fillRect(0,H-baseH*0.35,W,baseH*0.35+1);
      for(let i=0;i<count;i++){
        const x=R()*W, h=baseH*(0.6+R()*0.8), w=h*(0.22+R()*0.14), conifer=R()<0.65;
        wrap(x,w,(xx)=>{ c.beginPath();
          if(conifer){ c.moveTo(xx,H-h); c.lineTo(xx+w,H-baseH*0.25); c.lineTo(xx-w,H-baseH*0.25); }
          else { c.arc(xx,H-h*0.7,w*1.3,0,Math.PI*2); }
          c.fill(); });
      }
    }
  } else if(kind==='turbines'){
    cv._turbines=[];
    const n=12+Math.floor(R()*6);
    for(let i=0;i<n;i++){
      /* keep turbines apart so two rotors never overlap on screen */
      let x=R()*W; for(let t=0;t<40&&(cv._tx||[]).some(q=>{const d=Math.abs(q-x);return Math.min(d,W-d)<W*0.025;});t++)x=R()*W;
      (cv._tx||(cv._tx=[])).push(x);
      const depth=0.75+R()*0.25, h=H*0.85*depth, bl=h*0.40, a0=R()*6.28, rate=0.35+R()*0.35;   // 64-85% of the layer: always taller than backdrop trees
      const col=hsla(hue,10,night?(24+depth*8):(88-depth*26),0.65+0.35*depth);
      wrap(x,bl,(xx)=>{
        c.strokeStyle=col; c.fillStyle=col; c.lineCap='round';
        c.lineWidth=Math.max(1,h*0.025); c.beginPath(); c.moveTo(xx,H); c.lineTo(xx,H-h); c.stroke();
        if(night){ c.fillStyle='rgba(255,60,50,0.85)'; c.fillRect(xx-1,H-h-2,3,3); }   // steady, not blinking
        // Blades are NOT painted: they turn slowly each frame (drawSceneryLayers).
        /* ONE blade entry per turbine (the draw handles the wrap). Wrapped copies
           used to push their own entry with a different random speed, so two
           rotors turned out of step on the same spot — six spokes. */
        if(xx===x)cv._turbines.push({x:xx,hy:H-h,bl:bl,w:Math.max(1,h*0.018),col:col,ph:a0,rate:rate});
      });
    }
  } else if(kind==='spires'){
    for(let row=0;row<2;row++){
      const near=row===1, n=near?9:14;
      for(let i=0;i<n;i++){
        const x=R()*W, h=H*(near?0.90:0.60)*(0.45+R()*0.55), w=h*(0.07+R()*0.05);
        wrap(x,w*2,(xx)=>{
          const g=c.createLinearGradient(xx-w,0,xx+w,0);
          g.addColorStop(0,hsla(hue-25,night?45:30,night?(near?12:18):(near?28:44),0.95));
          g.addColorStop(0.5,hsla(hue+15,night?60:40,night?(near?32:40):(near?58:72),0.95));
          g.addColorStop(1,hsla(hue-25,night?45:30,night?(near?9:14):(near?22:38),0.95));
          c.fillStyle=g; c.beginPath(); c.moveTo(xx-w,H); c.lineTo(xx-w*0.35,H-h*0.85); c.lineTo(xx,H-h); c.lineTo(xx+w*0.35,H-h*0.85); c.lineTo(xx+w,H); c.closePath(); c.fill();
          if(night){ c.fillStyle=hsla(hue+15,80,72,0.35); c.fillRect(xx-0.5,H-h,1,h*0.6); }   // soft edge glow line
        });
      }
    }
  } else if(kind==='volcanoes'){
    const n=2+Math.floor(R()*3);
    for(let i=0;i<n;i++){
      const x=(i+0.2+R()*0.6)/n*W, h=H*(0.45+R()*0.25), w=h*(1.1+R()*0.6), cw=Math.min(w*0.12,(H-h)/2.4);
      wrap(x,w,(xx)=>{
        const g=c.createLinearGradient(0,H-h,0,H);
        g.addColorStop(0,hsla(hue+10,20,night?12:34,0.9)); g.addColorStop(1,hsla(hue,24,night?7:24,0.95));
        c.fillStyle=g; c.beginPath(); c.moveTo(xx-w,H); c.quadraticCurveTo(xx-w*0.35,H-h*0.6,xx-cw,H-h);
        c.lineTo(xx+cw,H-h); c.quadraticCurveTo(xx+w*0.35,H-h*0.6,xx+w,H); c.closePath(); c.fill();
        const rg=c.createRadialGradient(xx,H-h,0,xx,H-h,cw*2.2);          // faint crater glow (fits the layer)
        rg.addColorStop(0,'rgba(255,120,40,'+(night?0.55:0.25)+')'); rg.addColorStop(1,'rgba(255,80,20,0)');
        c.fillStyle=rg; c.beginPath(); c.arc(xx,H-h,cw*2.2,0,Math.PI*2); c.fill();
      });
    }
  } else if(kind==='icebergs'){
    const n=11+Math.floor(R()*6);
    for(let i=0;i<n;i++){
      const x=R()*W, h=H*(0.18+R()*0.40), w=h*(1.0+R()*1.4), pk=0.2+R()*0.6;
      wrap(x,w,(xx)=>{
        c.fillStyle=hsla(hue-10,30,night?(22+R()*6):(88-R()*8),0.92);
        c.beginPath(); c.moveTo(xx-w,H); c.lineTo(xx-w*0.6,H-h*0.55); c.lineTo(xx-w+w*2*pk,H-h); c.lineTo(xx+w*0.7,H-h*0.45); c.lineTo(xx+w,H); c.closePath(); c.fill();
        c.fillStyle=hsla(hue-5,40,night?14:70,0.6);                          // shaded face
        c.beginPath(); c.moveTo(xx-w+w*2*pk,H-h); c.lineTo(xx+w*0.7,H-h*0.45); c.lineTo(xx+w,H); c.lineTo(xx-w+w*2*pk,H); c.closePath(); c.fill();
      });
    }
  } else if(kind==='pylons'){
    const n=7+Math.floor(R()*3), sp=W/n, h=H*0.62, col=hsla(hue,10,night?38:30,0.9);
    c.strokeStyle=col; c.lineWidth=1;
    for(let i=0;i<n;i++){
      const xx=(i+0.5)*sp, top=H-h;
      c.lineWidth=Math.max(1,h*0.02); c.beginPath();
      c.moveTo(xx-h*0.12,H); c.lineTo(xx,top); c.lineTo(xx+h*0.12,H);
      c.moveTo(xx-h*0.16,top+h*0.12); c.lineTo(xx+h*0.16,top+h*0.12);
      c.moveTo(xx-h*0.12,top+h*0.28); c.lineTo(xx+h*0.12,top+h*0.28); c.stroke();
      c.lineWidth=1; c.beginPath();                                           // sagging cables to the next pylon (wraps)
      for(const o of [-0.16,0.16]){ const x2=xx+sp, y=top+h*0.12;
        c.moveTo(xx+o*h,y); c.quadraticCurveTo(xx+sp*0.5+o*h,y+h*0.10,x2+o*h,y); }
      c.stroke();
    }
  } else if(kind==='palms'){
    const n=16+Math.floor(R()*10);
    for(let i=0;i<n;i++){
      const x=R()*W, h=H*(0.25+R()*0.20), lean=(R()-0.5)*h*0.35, col=hsla(hue+100,25,night?7:22,0.9);   // never taller than a windmill
      wrap(x,h*0.6,(xx)=>{
        c.strokeStyle=col; c.fillStyle=col; c.lineWidth=Math.max(1,h*0.03); c.lineCap='round';
        const tx=xx+lean, ty=H-h;
        c.beginPath(); c.moveTo(xx,H); c.quadraticCurveTo(xx+lean*0.2,H-h*0.5,tx,ty); c.stroke();
        c.lineWidth=Math.max(1,h*0.025);
        for(let k=0;k<6;k++){ const a=-Math.PI*0.95+k*(Math.PI*0.9/5); const fl=h*(0.28+R()*0.1);
          c.beginPath(); c.moveTo(tx,ty); c.quadraticCurveTo(tx+Math.cos(a)*fl*0.6,ty+Math.sin(a)*fl*0.6-fl*0.15,tx+Math.cos(a)*fl,ty+Math.sin(a)*fl*0.4+fl*0.25); c.stroke(); }
      });
    }
  } else if(kind==='deadtrees'){
    const n=14+Math.floor(R()*10);
    const branch=(x,y,len,ang,depth)=>{ if(depth<=0||len<2)return;
      const x2=x+Math.cos(ang)*len, y2=y+Math.sin(ang)*len;
      c.lineWidth=Math.max(0.6,len*0.12); c.beginPath(); c.moveTo(x,y); c.lineTo(x2,y2); c.stroke();
      branch(x2,y2,len*0.7,ang-0.45-R()*0.3,depth-1); branch(x2,y2,len*0.65,ang+0.4+R()*0.3,depth-1); };
    for(let i=0;i<n;i++){
      const x=R()*W, h=H*(0.22+R()*0.20), col=hsla(hue-20,12,night?18:20,0.9);   // never taller than a windmill
      wrap(x,h*0.5,(xx)=>{ c.strokeStyle=col; c.lineCap='round'; branch(xx,H,h*0.42,-Math.PI/2+(R()-0.5)*0.2,4); });
    }
  } else if(kind==='domes'){
    const n=7+Math.floor(R()*4);
    for(let i=0;i<n;i++){
      const x=R()*W, r=H*(0.20+R()*0.22);
      wrap(x,r,(xx)=>{
        const g=c.createRadialGradient(xx-r*0.3,H-r*0.8,r*0.1,xx,H,r*1.1);
        g.addColorStop(0,hsla(hue+20,30,night?30:80,0.95)); g.addColorStop(1,hsla(hue,25,night?10:40,0.95));
        c.fillStyle=g; c.beginPath(); c.arc(xx,H,r,Math.PI,0); c.closePath(); c.fill();
        c.fillStyle=night?'rgba(255,220,140,0.75)':hsla(hue+20,40,90,0.5);     // softly lit windows, steady
        for(let k=0;k<4;k++){ const a=Math.PI+(k+0.5)/4*Math.PI; c.fillRect(xx+Math.cos(a)*r*0.72-1,H+Math.sin(a)*r*0.45-1,2.5,2); }
      });
    }
  } else if(kind==='monoliths'){
    const n=10+Math.floor(R()*8);
    for(let i=0;i<n;i++){
      const x=R()*W, h=H*(0.14+R()*0.26), w=h*(0.14+R()*0.18), tilt=(R()-0.5)*w*0.4;   // standing stones, not towers over the skyline
      wrap(x,w*2,(xx)=>{
        c.fillStyle=hsla(hue-10,12,night?8:26,0.9);
        c.beginPath(); c.moveTo(xx-w,H); c.lineTo(xx-w*0.8+tilt,H-h); c.lineTo(xx+w*0.8+tilt,H-h*0.96); c.lineTo(xx+w,H); c.closePath(); c.fill();
        c.fillStyle=hsla(hue+20,40,night?30:70,night?0.25:0.35);              // lit edge
        c.fillRect(xx-w*0.8+tilt,H-h,Math.max(1,w*0.25),h*0.95);
      });
    }
  }
  return cv;
}
/* Draw this track's layers for one tier ('far' or 'mid'). */
function drawSceneryLayers(ctx,tier,vw,vh,scroll,hue,night){
  try{
    const kinds=dm._scnKinds; if(!kinds||!kinds.length)return;
    const hz=(dm._horizonY!=null&&isFinite(dm._horizonY))?dm._horizonY:vh*0.62;
    const W=Math.max(2,Math.round(vw*2)), H=Math.max(8,Math.round(vh*(tier==='far'?0.30:0.24)));
    for(let i=0;i<kinds.length;i++){
      const k=kinds[i]; if(_SCN_KINDS[k].tier!==tier)continue;
      const key=(dm.seed>>>0)+'|'+k+'|'+W+'|'+H+'|'+(night?1:0);
      dm._scnCache=dm._scnCache||{};
      let cv=dm._scnCache[key];
      if(cv===undefined){
        for(const kk in dm._scnCache)if(kk.indexOf((dm.seed>>>0)+'|')!==0)delete dm._scnCache[kk];   // evict other tracks only
        cv=dm._scnCache[key]=_scnPaint(k,W,H,(dm.seed>>>0)^_scnHash(i+1),hue,night);
      }
      if(!cv)continue;
      const rate=(tier==='far'?0.35:0.65);
      const off=((Math.round(scroll*rate)%W)+W)%W;
      const y=Math.round(hz-H+2);
      ctx.drawImage(cv,-off,y); ctx.drawImage(cv,W-off,y);
      if(cv._turbines){                              // slowly turning blades
        const tt=(typeof performance!=='undefined'?performance.now():0)/1000;
        ctx.save(); ctx.lineCap='round';
        for(const tb of cv._turbines){
          for(const base of [-off,W-off]){
            const hx=tb.x+base, hy=tb.hy+y; if(hx<-tb.bl||hx>vw+tb.bl)continue;
            ctx.strokeStyle=tb.col; ctx.lineWidth=tb.w; ctx.beginPath();
            for(let k=0;k<3;k++){ const a=tb.ph+tt*tb.rate+k*2.0944; ctx.moveTo(hx,hy); ctx.lineTo(hx+Math.cos(a)*tb.bl,hy+Math.sin(a)*tb.bl); }
            ctx.stroke();
          }
        }
        ctx.restore();
      }
    }
  }catch(e){}
}
/* ═══ ROADSIDE ENVIRONMENTS — wide, logical, GPU-cheap
   The roadside used to be props planted 2-4 road half-widths from the centre
   line, with extra plants stacked in that same strip, so the world ended just
   past the kerb and looked cluttered. This system adds a separate landscape:
   • ZONES — each biome has 3 environments that change along the track
     (e.g. pine forest -> meadow -> rocky clearing), 400-1000 segments each.
   • LOGICAL PLACEMENT — items are grouped the way landscapes are (groves,
     scattered singles, crop rows, farmsteads). Cluster centres sit mostly in a
     MID band (4-10 half-widths) and a FAR band (10-32); only small, sparse
     items come near the road. Far items only enter the screen in the
     distance, which is what makes the world read as wide.
   • GPU-CHEAP — every kind is painted once per track into ONE atlas canvas,
     pre-tinted to the environment and with a distance-haze row baked in. Each
     item on screen is then a single drawImage() from that atlas — a texture
     blit on the GPU in browser canvases — with no per-frame paths, colour or
     alpha state changes. Hill crests crop items via the source rectangle.
   • GENERATION — laid out by a final build pass into compact typed arrays,
     hashed from the seed (never rng()), so no track changes shape and the
     Super Racing preview still matches the race. */
const ST_ENV=4;
const ST_DECK=5;   // overpass crossing decks (see PSEUDO-3D MULTI-TIERED OVERPASS)
/* ═══ 100 DIFFERENT SET PIECES
   16 hand-built ones plus 84 generated ones. Each generated set piece pairs
   one of 12 object shapes with one of 10 motions — a UNIQUE pairing, so no two
   share one — and adds its own placement, colour, spacing, and sometimes a road
   surface, a full-screen effect and an elevation profile. */
/* Neutral per-set-piece modifiers (kept for the drawing code; every set piece
   is now its own design, so only the default entry exists). */
const SP_VARIANTS=[{name:'',scale:1.0,spd:1.0,prism:0,chaos:0,elev:1.0,boost:0}];
const SP_BESPOKE=['ring','rainbow','plunge','camelback','strobe','lava','hyper','fireworks','disco',
  'swoops','warp','neon','wave','meteor','colossus','confetti'];
const SP_BESPOKE_NAMES=['RING GAUNTLET','RAINBOW ROAD','SKY PLUNGE','CAMELBACK HOPS','STROBE GATES','LAVA RUN','HYPER LANE',
  'FIREWORK ALLEY','DISCO FLOOR','VALLEY SWOOPS','WARP DRIVE','NEON GRID','TIDAL WAVE','METEOR SHOWER','COLOSSUS ARCHES','CONFETTI CANNONS'];
const SPG_SHAPES=['hoop','arch','pillar','block','orb','diamond','star','pyramid','beam','flame','cube','totem'];
const SPG_SHNAME=['HOOPS','ARCHES','PILLARS','MONOLITHS','ORBS','DIAMONDS','STARS','PYRAMIDS','BEAMS','FLAMES','CUBES','TOTEMS'];
const SPG_MOT=['float','spin','erupt','pulse','sway','orbit','strobe','rain','sweep','bounce'];
const SPG_MONAME=['FLOATING','SPINNING','ERUPTING','PULSING','SWAYING','ORBITING','STROBING','RAINING','SWEEPING','BOUNCING'];
const SPG_PLACE=['both','center','alt','zigzag','wide'];
const SPG_SURF=[null,'stripes','checker','pulse','zebra','ember','ice','toxic','gold','void','candy'];
const SPG_OV=[null,'flash','starfield','sparks','vignette','scan','aurora','snow','hearts'];
const SPG_ELEV=[null,'hop','dip','wave'];
const SP_GEN=[];
for(let i=0;i<84;i++){
  const a=i%12, b=Math.floor(i/12), m=(a+3*b)%10;          // unique (shape, motion) pair for every i
  SP_GEN.push({shape:SPG_SHAPES[a], mot:SPG_MOT[m], place:SPG_PLACE[(i*3+b)%5], surf:SPG_SURF[(i*7)%11],
    ov:SPG_OV[(i*5+b)%9], elev:SPG_ELEV[(i*11)%4], hue:(i*137)%360, every:5+(i*3)%9,
    name:SPG_MONAME[m]+' '+SPG_SHNAME[a]});
}
const SP_KINDS=SP_BESPOKE.concat(SP_GEN.map((g,i)=>'g'+i));        // 100 kinds
const SP_NAMES=SP_BESPOKE_NAMES.concat(SP_GEN.map(g=>g.name));
const ST_RING=6;   // Ring Gauntlet hoops (see HIGH-ENERGY SET PIECES)
/* ── Generated set pieces: shape x motion x placement ─────────────────────── */
function _spgShape(shape,x,y,r,rot,col){
  ctx.save(); ctx.translate(x,y); if(rot)ctx.rotate(rot);
  ctx.fillStyle=col; ctx.strokeStyle=col; ctx.lineWidth=Math.max(1.5,r*0.14);
  ctx.beginPath();
  if(shape==='hoop'){ ctx.ellipse(0,0,r,r,0,0,Math.PI*2); ctx.stroke(); }
  else if(shape==='arch'){ ctx.ellipse(0,r*0.5,r,r,0,Math.PI,Math.PI*2); ctx.stroke(); }
  else if(shape==='pillar'){ ctx.rect(-r*0.22,-r,r*0.44,r*2); ctx.fill(); }
  else if(shape==='block'){ ctx.rect(-r*0.5,-r*1.2,r,r*2.4); ctx.fill(); }
  else if(shape==='orb'){ ctx.arc(0,0,r*0.6,0,Math.PI*2); ctx.fill(); }
  else if(shape==='diamond'){ ctx.moveTo(0,-r); ctx.lineTo(r*0.6,0); ctx.lineTo(0,r); ctx.lineTo(-r*0.6,0); ctx.closePath(); ctx.fill(); }
  else if(shape==='star'){ for(let k=0;k<10;k++){ const an=k*Math.PI/5-Math.PI/2, rr=(k&1)?r*0.42:r; k?ctx.lineTo(Math.cos(an)*rr,Math.sin(an)*rr):ctx.moveTo(Math.cos(an)*rr,Math.sin(an)*rr); } ctx.closePath(); ctx.fill(); }
  else if(shape==='pyramid'){ ctx.moveTo(0,-r); ctx.lineTo(r*0.8,r*0.6); ctx.lineTo(-r*0.8,r*0.6); ctx.closePath(); ctx.fill(); }
  else if(shape==='beam'){ ctx.rect(-r*1.6,-r*0.12,r*3.2,r*0.24); ctx.fill(); }
  else if(shape==='flame'){ ctx.moveTo(0,-r); ctx.quadraticCurveTo(r*0.7,0,0,r*0.6); ctx.quadraticCurveTo(-r*0.7,0,0,-r); ctx.fill(); }
  else if(shape==='cube'){ ctx.rect(-r*0.5,-r*0.5,r,r); ctx.fill(); ctx.fillStyle='rgba(255,255,255,0.35)'; ctx.fillRect(-r*0.5,-r*0.5,r,r*0.2); }
  else if(shape==='totem'){ for(let k=0;k<3;k++){ ctx.rect(-r*0.35+(k&1)*r*0.08,-r+k*r*0.7,r*0.7-(k&1)*r*0.16,r*0.6); } ctx.fill(); }
  ctx.restore();
}
function _drawGen(sp,vw,vh){
  const s=sp.s, p=s.p1.screen, n=sp.n||0; if(!(p.w>0))return;
  const G=SP_GEN[s._spG|0]; if(!G)return;
  const ws=s._wScale||1, b=p.w/ws, t=animNow(), I=s._spI||0, clip=Math.min((s._envClip!=null)?s._envClip:vh,vh);
  const near=Math.max(0,Math.min(1,(40-n)/30)), ne=near*near*(3-2*near);
  ctx.save(); ctx.beginPath(); ctx.rect(0,0,vw,Math.max(0,clip)); ctx.clip();
  // anchors from placement
  const pts=[];
  if(G.place==='both'){ pts.push([p.x-(p.w+b*0.9),-1],[p.x+(p.w+b*0.9),1]); }
  else if(G.place==='wide'){ pts.push([p.x-(p.w+b*2.6),-1],[p.x+(p.w+b*2.6),1]); }
  else if(G.place==='alt'){ const sd=(I&1)?1:-1; pts.push([p.x+sd*(p.w+b*1.0),sd]); }
  else if(G.place==='zigzag'){ pts.push([p.x+Math.sin(I*0.9)*p.w*0.7,0]); }
  else pts.push([p.x,0]);                                             // center (overhead)
  const r=b*(G.place==='center'||G.place==='zigzag'?0.7:0.55);
  for(const [ax,sd] of pts){
    const baseY=(sd===0)?p.y-b*1.8:p.y-r*1.1;
    let x=ax, y=baseY, rr=r, rot=0, a=1;
    const ph=t*0.001+I*0.7;
    if(G.mot==='float'){ y-=Math.sin(ph*2)*b*0.25; }
    else if(G.mot==='spin'){ rot=ph*3; }
    else if(G.mot==='erupt'){ y=p.y-(p.y-baseY)*ne; rr=r*(0.3+0.7*ne); }
    else if(G.mot==='pulse'){ rr=r*(0.75+0.35*Math.sin(ph*6)); }
    else if(G.mot==='sway'){ x+=Math.sin(ph*2.5)*b*0.6; rot=Math.sin(ph*2.5)*0.3; }
    else if(G.mot==='orbit'){ x+=Math.cos(ph*3)*b*0.6; y+=Math.sin(ph*3)*b*0.35; }
    else if(G.mot==='strobe'){ a=((Math.floor(t/110)+I)%3===0)?1:0.25; }
    else if(G.mot==='rain'){ y=baseY-b*3+((t*0.002+I*0.37)%1)*b*3; }
    else if(G.mot==='sweep'){ x=p.x+Math.sin(ph*1.8)*(p.w+b*1.5); }
    else if(G.mot==='bounce'){ y-=Math.abs(Math.sin(ph*4))*b*0.8; }
    if(y-rr>clip)continue;
    ctx.globalAlpha=a;
    _spgShape(G.shape,x,y,rr,rot,'hsl('+((G.hue+I*23)%360)+',90%,60%)');
  }
  ctx.globalAlpha=1;
  ctx.restore();
}
/* Full-screen effects for generated set pieces while the player is inside. */
function _spgOverlay(G,vw,vh,t){
  const ov=G.ov; if(!ov)return;
  ctx.save();
  if(ov==='flash'){ const a=Math.max(0,Math.sin(t*0.012))*0.12; ctx.fillStyle='hsla('+G.hue+',100%,70%,'+a.toFixed(3)+')'; ctx.fillRect(0,0,vw,vh); }
  else if(ov==='starfield'){ ctx.fillStyle='rgba(255,255,255,0.8)'; for(let k=0;k<60;k++){ const x=((k*197+t*0.05*(1+k%3))%vw), y=((k*83)%Math.max(1,(dm._horizonY||vh*0.5))); ctx.fillRect(x,y,2,2); } }
  else if(ov==='sparks'){ for(let k=0;k<40;k++){ const ph=((t*0.001+k*0.137)%1); ctx.fillStyle='hsla('+((G.hue+k*9)%360)+',100%,65%,'+(1-ph).toFixed(2)+')'; ctx.fillRect(((k*211)%vw),vh*(1-ph*0.9),3,3); } }
  else if(ov==='vignette'){ const a=0.25+0.15*Math.sin(t*0.006); ctx.strokeStyle='hsla('+G.hue+',100%,50%,'+a.toFixed(2)+')'; ctx.lineWidth=vh*0.08; ctx.strokeRect(0,0,vw,vh); }
  else if(ov==='scan'){ const y=((t*0.4)%vh); ctx.fillStyle='hsla('+G.hue+',100%,70%,0.18)'; ctx.fillRect(0,y,vw,vh*0.04); }
  else if(ov==='aurora'){ const gr=ctx.createLinearGradient(0,0,vw,0); for(let k=0;k<=4;k++)gr.addColorStop(k/4,'hsla('+((G.hue+k*40+t*0.02)%360)+',90%,60%,0.10)'); ctx.fillStyle=gr; ctx.fillRect(0,0,vw,(dm._horizonY||vh*0.5)*0.8); }
  else if(ov==='snow'){ ctx.fillStyle='rgba(255,255,255,0.85)'; for(let k=0;k<70;k++){ const x=((k*173+Math.sin(t*0.001+k)*30)%vw+vw)%vw, y=((k*97+t*0.12*(1+k%4))%vh); ctx.fillRect(x,y,2.5,2.5); } }
  else if(ov==='hearts'){ ctx.fillStyle='rgba(255,90,150,0.8)'; ctx.font=Math.round(vh*0.03)+'px sans-serif'; for(let k=0;k<14;k++){ const x=((k*251)%vw), y=vh-((t*0.08+k*61)%vh); ctx.fillText('\u2665',x,y); } }
  ctx.restore();
}
/* Road-surface colour for surface set pieces (null = normal road). */
/* ═══ ROAD SURFACE MATERIALS (engine plan E9)
   A segment may carry `surf`: its deck colour and, in updatePlayer, its
   grip and rolling drag. Asphalt is the absence of a material. Ice slides,
   sand drags, metal grating bites, glass shows the ground (or the void)
   through it. Used by the SURFACE track types (plan part 3). */
const SURFACES={
  ice:  {grip:0.42,drag:0.000,col:(d,i)=>d?'hsl(196,52%,68%)':'hsl(196,60%,78%)'},
  dirt: {grip:0.78,drag:0.035,col:(d,i)=>d?'hsl(26,38%,27%)':'hsl(28,42%,33%)'},
  sand: {grip:0.70,drag:0.070,col:(d,i)=>d?'hsl(40,48%,54%)':'hsl(42,56%,62%)'},
  metal:{grip:1.08,drag:0.000,col:(d,i)=>((i>>1)&1)?'hsl(210,10%,36%)':'hsl(210,8%,47%)'},
  glass:{grip:0.92,drag:0.000,col:(d,i)=>(i%6===0)?'rgba(215,248,255,0.85)':(d?'rgba(110,190,255,0.34)':'rgba(160,220,255,0.28)')},
  lava: {grip:0.95,drag:0.020,col:(d,i)=>'hsl('+(6+(i*7)%18)+',88%,'+(d?17:23)+'%)'},
  grass:{grip:0.66,drag:0.050,col:(d,i)=>d?'hsl(104,44%,27%)':'hsl(108,50%,33%)'}
};
function _surfColor(s,dark){ const S=s.surf&&SURFACES[s.surf]; return S?S.col(dark,s.index|0):null; }
function _spSurface(s,dark){
  const k=s._sp; if(k==null)return null; const kind=SP_KINDS[k], V=SP_VARIANTS[s._spV|0]||SP_VARIANTS[0], t=animNow()*V.spd;
  if(V.prism&&(kind==='lava'||kind==='disco'))return 'hsl('+((s.index*14+t*0.25)%360).toFixed(0)+',90%,50%)';
  if(V.chaos&&kind==='neon'&&((s.index+Math.floor(t/120))%7===0))return '#2a0030';
  if(kind.charAt(0)==='g'){ const G=SP_GEN[+kind.slice(1)], su=G.surf, hh=G.hue, i2=s.index;
    if(!su)return null;
    if(su==='stripes')return (i2>>1)&1?'hsl('+hh+',70%,45%)':'hsl('+((hh+180)%360)+',60%,25%)';
    if(su==='checker')return ((i2>>2)&1)?'#e8e8f0':'#14141c';
    if(su==='pulse')return 'hsl('+hh+',80%,'+(25+20*(0.5+0.5*Math.sin(i2*0.3-t*0.008))).toFixed(0)+'%)';
    if(su==='zebra')return (i2%3===0)?'#f4f4f4':'#111';
    if(su==='ember')return 'hsl('+(10+(i2*7)%30)+',90%,'+(22+(i2*13)%18)+'%)';
    if(su==='ice')return 'hsl(195,70%,'+(60+(i2*5)%20)+'%)';
    if(su==='toxic')return 'hsl('+(95+(i2*3)%30)+',90%,'+(30+10*Math.sin(t*0.004+i2*0.2)).toFixed(0)+'%)';
    if(su==='gold')return 'hsl(45,85%,'+(40+(i2*9)%20)+'%)';
    if(su==='void')return '#020205';
    if(su==='candy')return 'hsl('+((i2*40)%360)+',80%,70%)';
    return null; }
  if(kind==='rainbow')return 'hsl('+((s.index*9+t*0.06)%360).toFixed(0)+','+(dark?'90%,42':'75%,48')+'%)';
  if(kind==='lava'){ const q=0.5+0.5*Math.sin(s.index*0.35-t*0.006); return 'hsl('+(8+q*22).toFixed(0)+',95%,'+(26+q*22).toFixed(0)+'%)'; }
  if(kind==='disco'){ const on=((s.index>>2)+Math.floor(t/260))&1; return on?'hsl('+((s.index*37+Math.floor(t/260)*80)%360)+',85%,55%)':'#101018'; }
  if(kind==='neon')return '#07070f';
  return null;
}
/* On-road patterns drawn over the deck: Hyper Lane chevrons, Neon Grid lines. */
function _spDeckFx(s,p1,p2){
  const k=s._sp; if(k==null)return; const kind=SP_KINDS[k], t=animNow()*((SP_VARIANTS[s._spV|0]||SP_VARIANTS[0]).spd);
  if(kind==='hyper'){
    if(((s.index+Math.floor(t/40))%6)<2){ const c='hsla('+((t*0.2)%360)+',100%,65%,0.85)';
      poly(p1.x-p1.w*0.55,p1.y,p1.x,p1.y-(p1.y-p2.y)*0.2,p1.x+p1.w*0.55,p1.y,p2.x+p2.w*0.55,p2.y,c);
      poly(p1.x-p1.w*0.55,p1.y,p2.x-p2.w*0.55,p2.y,p2.x,p2.y-(p1.y-p2.y)*0.2,p1.x,p1.y-(p1.y-p2.y)*0.2,c); }
  } else if(kind==='neon'){
    const c='hsla('+((190+t*0.05)%360)+',100%,62%,0.9)';
    for(let L=-1;L<=1;L+=0.5){ const lw1=Math.max(0.6,p1.w*0.025), lw2=Math.max(0.6,p2.w*0.025);
      poly(p1.x+L*p1.w-lw1,p1.y,p1.x+L*p1.w+lw1,p1.y,p2.x+L*p2.w+lw2,p2.y,p2.x+L*p2.w-lw2,p2.y,c); }
    if(s.index%6===0){ ctx.fillStyle=c; ctx.fillRect(p1.x-p1.w,p1.y-Math.max(1,(p1.y-p2.y)*0.3),p1.w*2,Math.max(1,(p1.y-p2.y)*0.3)); }
  }
}
/* Object set pieces: each reacts to distance (n) and time for surprise. */
function _drawSP(sp,vw,vh){
  const s=sp.s, p=s.p1.screen, kind=s._spk, n=sp.n||0; if(!(p.w>0))return;
  const V=SP_VARIANTS[s._spV|0]||SP_VARIANTS[0];
  const ws=s._wScale||1, b=(p.w/ws)*V.scale, t=animNow()*V.spd, clip=Math.min((s._envClip!=null)?s._envClip:vh,vh);
  const near=Math.max(0,Math.min(1,(40-n)/30)), I=(s._spI||0)+(V.prism?Math.floor(t/140):0);
  if(V.chaos){ ctx.save(); ctx.translate(Math.sin(I*1.7+t*0.004)*b*0.7,0); }
  ctx.save(); ctx.beginPath(); ctx.rect(0,0,vw,Math.max(0,clip)); ctx.clip();
  if(kind==='strobe'||kind==='colossus'){
    const big=kind==='colossus'?3.2:1.7, R=b*big, cy=p.y-R*0.72;
    ctx.beginPath(); ctx.rect(0,0,vw,Math.max(0,Math.min(clip,p.y))); ctx.clip();
    const on=kind==='strobe'?(((Math.floor(t/90)+I)%5)===0):true;
    const h=kind==='colossus'?((I*47+t*0.03)%360):0;
    ctx.lineWidth=Math.max(2,R*(kind==='colossus'?0.10:0.07));
    ctx.strokeStyle=kind==='strobe'?(on?'rgba(255,255,255,1)':'rgba(120,130,160,0.35)'):'hsla('+h+',100%,62%,0.95)';
    ctx.beginPath(); ctx.ellipse(p.x,cy,R*1.05,R,0,0,Math.PI*2); ctx.stroke();
    if(on&&kind==='strobe'){ ctx.lineWidth*=3; ctx.strokeStyle='rgba(255,255,255,0.25)'; ctx.stroke(); }
  } else if(kind==='popup'){
    const up=near*near*(3-2*near);
    for(const sd of [-1,1]){ const h2=b*(0.6+((I*7+sd+2)%5)*0.25)*up, w2=b*0.55, x=p.x+sd*(p.w+b*0.9);
      ctx.fillStyle='hsl('+((I*53+(sd>0?120:0))%360)+',90%,55%)'; ctx.fillRect(x-w2/2,p.y-h2,w2,h2);
      ctx.fillStyle='rgba(255,255,255,0.5)'; ctx.fillRect(x-w2/2,p.y-h2,w2,Math.max(1,h2*0.08)); }
  } else if(kind==='fireworks'){
    if(n<45){ if(!s._fwT)s._fwT=t; const age=(t-s._fwT)/900;
      if(age<1.4){ const cx=p.x+((I%3)-1)*b*1.2, cy=p.y-b*(2.2+(I%2)*0.8), R=b*1.8*Math.min(1,age*1.6), a=Math.max(0,1-age/1.4);
        for(let k=0;k<18;k++){ const an=k/18*Math.PI*2; ctx.fillStyle='hsla('+((I*61+k*20)%360)+',100%,65%,'+a.toFixed(2)+')';
          ctx.fillRect(cx+Math.cos(an)*R-1.5,cy+Math.sin(an)*R*0.8-1.5,Math.max(2,b*0.08),Math.max(2,b*0.08)); } } }
    else s._fwT=0;
  } else if(kind==='gems'){
    const spin=Math.cos(t*0.006+I), gy=p.y-b*(0.9+0.15*Math.sin(t*0.004+I)), gs=b*0.32;
    ctx.fillStyle='hsl('+((I*41)%360)+',90%,60%)';
    ctx.beginPath(); ctx.moveTo(p.x,gy-gs); ctx.lineTo(p.x+gs*spin,gy); ctx.lineTo(p.x,gy+gs); ctx.lineTo(p.x-gs*spin,gy); ctx.closePath(); ctx.fill();
  } else if(kind==='wave'){
    const rise=near*near*(3-2*near), sd=((I>>3)&1)?1:-1, x=p.x+sd*(p.w+b*1.2), H2=b*4.5*rise;
    ctx.fillStyle='rgba(40,140,230,0.85)';
    ctx.beginPath(); ctx.moveTo(x-sd*b*0.2,p.y); ctx.quadraticCurveTo(x+sd*b*1.5,p.y-H2*0.4,x+sd*b*0.6,p.y-H2);
    ctx.quadraticCurveTo(x-sd*b*0.8,p.y-H2*1.1,x-sd*b*1.2,p.y-H2*0.75); ctx.lineTo(x+sd*b*3.5,p.y); ctx.closePath(); ctx.fill();
    ctx.fillStyle='rgba(235,248,255,0.8)'; ctx.fillRect(x-b*1.2,p.y-H2-b*0.08,b*1.8,Math.max(1,b*0.12));
  } else if(kind==='pinball'){
    const lit=n<6?1:(0.35+0.25*Math.sin(t*0.01+I));
    for(const sd of [-1,1]){ const x=p.x+sd*(p.w+b*0.45), r=b*0.34;
      ctx.fillStyle='hsla('+((I*29+(sd>0?180:0))%360)+',100%,'+(40+lit*25).toFixed(0)+'%,1)';
      ctx.beginPath(); ctx.arc(x,p.y-r,r,0,Math.PI*2); ctx.fill();
      ctx.strokeStyle='rgba(255,255,255,'+(0.4+lit*0.6).toFixed(2)+')'; ctx.lineWidth=Math.max(1,r*0.18); ctx.stroke(); }
  } else if(kind==='laser'){
    const yy=p.y-b*(0.5+0.9*(0.5+0.5*Math.sin(t*0.004+I)));
    ctx.fillStyle='rgba(255,40,60,0.85)'; ctx.fillRect(p.x-p.w*1.3,yy,p.w*2.6,Math.max(1,b*0.05));
    ctx.fillStyle='rgba(255,120,130,0.35)'; ctx.fillRect(p.x-p.w*1.3,yy-b*0.05,p.w*2.6,Math.max(2,b*0.15));
    ctx.fillStyle='#333'; ctx.fillRect(p.x-p.w*1.35,yy-b*0.3,b*0.12,b*0.6); ctx.fillRect(p.x+p.w*1.23,yy-b*0.3,b*0.12,b*0.6);
  } else if(kind==='confetti'){
    if(n<30){ if(!s._cfT)s._cfT=t; const age=(t-s._cfT)/1000;
      if(age<1.6){ for(const sd of [-1,1]){ for(let k=0;k<22;k++){ const vx=sd*(-0.2-((k*37)%10)/10*1.4), vy=-1.6-((k*53)%10)/10*1.2;
          const x=p.x+sd*(p.w+b*0.6)+vx*b*age*1.4, y=p.y-b*0.4+(vy*age+1.4*age*age)*b;
          ctx.fillStyle='hsl('+((k*47+I*13)%360)+',95%,60%)'; ctx.fillRect(x,y,Math.max(2,b*0.07),Math.max(2,b*0.04)); } } } }
    else s._cfT=0;
  }
  if(V.chaos)ctx.restore();
  ctx.restore();
}
/* Full-screen set-piece overlays while the player is inside: Warp Drive star
   streaks and a Meteor Shower. */
function _spOverlay(vw,vh){
  if(!P)return; const g=seg(P.z); if(!g||g._sp==null)return;
  const kind=SP_KINDS[g._sp], t=animNow()*((SP_VARIANTS[g._spV|0]||SP_VARIANTS[0]).spd), cx=vw/2, cy=(dm._horizonY||vh*0.5);
  if(kind.charAt(0)==='g'){ const G=SP_GEN[+kind.slice(1)]; if(G)_spgOverlay(G,vw,vh,t); return; }
  if(kind==='warp'){
    ctx.save(); ctx.strokeStyle='rgba(220,235,255,0.55)'; ctx.lineWidth=1.5; ctx.beginPath();
    for(let k=0;k<70;k++){ const an=(k*2.39996)%(Math.PI*2), ph=((t*0.0022+k*0.137)%1), r0=ph*ph*vw*0.7, r1=r0+vw*0.05*ph;
      ctx.moveTo(cx+Math.cos(an)*r0,cy+Math.sin(an)*r0*0.7); ctx.lineTo(cx+Math.cos(an)*r1,cy+Math.sin(an)*r1*0.7); }
    ctx.stroke(); ctx.restore();
  } else if(kind==='meteor'){
    ctx.save();
    for(let k=0;k<5;k++){ const ph=((t*0.0006+k*0.23)%1), x0=((k*0.29+0.1)%1)*vw*1.2-vw*0.1, y0=-vh*0.1;
      const x=x0-ph*vw*0.35, y=y0+ph*cy*1.05;
      const gr=ctx.createLinearGradient(x,y,x+vw*0.06,y-vh*0.08); gr.addColorStop(0,'rgba(255,220,150,0.95)'); gr.addColorStop(1,'rgba(255,120,40,0)');
      ctx.strokeStyle=gr; ctx.lineWidth=3; ctx.beginPath(); ctx.moveTo(x,y); ctx.lineTo(x+vw*0.06,y-vh*0.08); ctx.stroke();
      ctx.fillStyle='rgba(255,245,220,1)'; ctx.beginPath(); ctx.arc(x,y,3,0,Math.PI*2); ctx.fill(); }
    ctx.restore();
  }
}

/* A glowing neon hoop around the road: a wide translucent halo stroke and a
   bright core, clipped at road level so the road passes through it. */
function drawRing(sp,vw,vh){
  const s=sp.s, p=s.p1.screen; if(!(p.w>0)||!s._ring)return;
  const ws=s._wScale||1, b=p.w/ws, R=b*1.6, cy=p.y-R*0.72;
  if(cy+R<0||cy-R>vh)return;
  const clip=Math.min((s._envClip!=null)?s._envClip:vh,p.y);
  ctx.save(); ctx.beginPath(); ctx.rect(0,0,vw,Math.max(0,clip)); ctx.clip();
  const h=(s._ring.hue+animNow()*0.04)%360;
  ctx.lineWidth=Math.max(2,R*0.16); ctx.strokeStyle='hsla('+h+',100%,60%,0.28)';
  ctx.beginPath(); ctx.ellipse(p.x,cy,R*1.05,R,0,0,Math.PI*2); ctx.stroke();
  ctx.lineWidth=Math.max(1.5,R*0.055); ctx.strokeStyle='hsla('+h+',100%,72%,0.95)';
  ctx.beginPath(); ctx.ellipse(p.x,cy,R*1.05,R,0,0,Math.PI*2); ctx.stroke();
  ctx.restore();
}
/* One crossing structure at a segment: 1-3 stacked bridge decks spanning the
   track, each on pillars down to the ground outside the rails, with a lit
   underside. Depth-sorted with the other sprites, so it covers the road beyond
   it and passes overhead as the camera drives under. */
/* ═══ CAMERA-OCCLUDER FADE (plan item 11)
   Cinematic poses swing the eye round, along and beside the machine, and a
   roadside building, crystal or bridge deck can end up between the lens and
   the car — or around the lens entirely. The pseudo-3D projector has no near
   plane to clip against, so instead of geometry this does what 3D games do:
   anything NEARER than the car that covers the car's screen box fades toward
   20%, continuously with the amount of cover (no popping), and anything that
   fills the frame — taller than 1.6 viewports and wider than half of it — is
   faded out as the eye enters it. Only active in cinematic views (attract,
   intro, debug viewpoint); the race camera is untouched. dm._occl is filled
   once per frame in renderWorld. */
function _occlK(depthZ,x0,x1,y0,y1,vw,vh){
  const O=dm._occl; if(!O||!O.on)return 1;
  let k=1;
  if(depthZ<O.depth-SEG_LEN*0.5){
    const ox=Math.min(x1,O.x1)-Math.max(x0,O.x0), oy=Math.min(y1,O.y1)-Math.max(y0,O.y0);
    if(ox>0&&oy>0){
      const f=Math.min(1,ox/(O.x1-O.x0))*Math.min(1,oy/(O.y1-O.y0));
      k=1-0.80*f*f*(3-2*f);
    }
  }
  const hh=y1-y0, ww=Math.min(x1,vw)-Math.max(x0,0);
  if(hh>vh*1.6&&ww>vw*0.5)k*=Math.max(0,1-(hh-vh*1.6)/(vh*0.6));
  return k;
}
function drawDeck(sp,vw,vh){
  /* ═══ A BRIDGE, NOT A FLOATING BAR
     The deck was a thin 11-half-width slab with a hue-tinted light strip and
     pillars only at the road edges; from a distance it read as a thin blue
     bar floating in the sky. It carries a real ROAD crossing the track, so it
     now spans the whole view, is a thicker concrete deck with a guard-rail
     line on top, an underside shadow and a row of steady lights, and stands
     on wide piers at both road edges plus further piers out to the screen
     edges — all standing on the ground. */
  const s=sp.s, p=s.p1.screen; if(!(p.w>0)||!s._decks)return;
  const clip=(s._envClip!=null)?s._envClip:vh;
  const ws=s._wScale||1, b=p.w/ws;                     // base half-width in px (1 unit of deck height)
  const night=isNight();
  /* A deck spans the whole view, so it occludes whenever its band crosses
     the car's box (plan item 11). */
  let _dTop=vh, _dBot=0;
  for(const d of s._decks){ const yb=p.y-d.h*b, yt=yb-Math.max(d.th,0.45)*b; if(yt<_dTop)_dTop=yt; if(yb>_dBot)_dBot=yb; }
  const _dk=_occlK(s.p1.camera.z,0,vw,_dTop,_dBot,vw,vh);
  if(_dk<=0.01)return;
  ctx.save(); ctx.beginPath(); ctx.rect(0,0,vw,Math.max(0,clip)); ctx.clip();
  if(_dk<1)ctx.globalAlpha*=_dk;
  const x0=Math.min(0,p.x-b*40), x1=Math.max(vw,p.x+b*40);
  const concrete=night?'#2c2d33':'#77726a', shade=night?'#18191e':'#4c4843', pier=night?'#25262c':'#6a655d';
  for(let q=s._decks.length-1;q>=0;q--){
    const d=s._decks[q], th=Math.max(d.th,0.45), yb=p.y-d.h*b, yt=yb-th*b;
    if(yb<-vh||yt>vh)continue;
    // piers: wide ones at both road edges, then every 6 half-widths outwards
    ctx.fillStyle=pier;
    const pw=Math.max(2,b*0.34);
    const piers=[p.x-p.w-b*0.25-pw, p.x+p.w+b*0.25];
    for(let k=1;k<8;k++){ piers.push(p.x-p.w-b*(0.25+6*k)-pw, p.x+p.w+b*(0.25+6*k)); }
    for(const px of piers){ if(px+pw<0||px>vw)continue; ctx.fillRect(px,yb,pw,Math.max(0,p.y-yb)); }
    // deck face, underside shadow, rail line on top, steady lights
    ctx.fillStyle=concrete; ctx.fillRect(x0,yt,x1-x0,yb-yt);
    ctx.fillStyle=shade; ctx.fillRect(x0,yb-(yb-yt)*0.30,x1-x0,(yb-yt)*0.30);
    ctx.fillStyle=theme.railL||'#ff7bd0'; ctx.fillRect(x0,yt-Math.max(1,(yb-yt)*0.16),x1-x0,Math.max(1,(yb-yt)*0.12));
    ctx.fillStyle=night?'rgba(255,214,140,0.9)':'rgba(255,236,190,0.75)';
    const step=Math.max(8,b*1.6), lh=Math.max(1,(yb-yt)*0.14);
    for(let lx=x0+((p.x%step)+step)%step;lx<x1;lx+=step)ctx.fillRect(lx,yt+(yb-yt)*0.35,Math.max(1,lh*1.4),lh);
  }
  ctx.restore();
}
