    tunnel:mkTunnel,straightaway:mkStraightaway,sideways:mkSideways,
    sweeparc:mkSweepArc,flowchain:mkFlowChain,openrun:mkOpenRun,
    downhillblast:mkDownhillBlast,crestsweep:mkCrestSweep,
    canyonrun:_mkCanyonRun,chicanewall:_mkChicaneWall,boostchain:_mkBoostChain,
    gravitywell:_mkGravityWell,skyramp:_mkSkyRamp,rumblezone:_mkRumbleZone,
    nightgate:_mkNightGate,
    longsweep:_mkSweep(1,5,2.2,1.2),    reversesweep:_mkSweep(-1,5,2.2,1.2),
    grandsweep:_mkSweep(1,7,1.4,0.8),   tightsweep:_mkSweep(-1,3,3.6,0.6),
    risingsweep:_mkSweep(1,4,1.8,3.0),  fallingsweep:_mkSweep(-1,4,1.8,-3.0),
    flatsweep:_mkSweep(1,6,1.1,0.0),    rollingsweep:_mkSweep(-1,6,1.6,2.0),
    kinkpair:_mkKink(2,4.5),  kinktriple:_mkKink(3,4.0), kinkrun:_mkKink(5,3.4),
    kinkstorm:_mkKink(8,3.0), softkinks:_mkKink(4,2.2),  sharpkinks:_mkKink(4,6.0),
    terrace2:_mkTerrace(2), terrace3:_mkTerrace(3), terrace4:_mkTerrace(4),
    terrace6:_mkTerrace(6),
    microsprint:_mkSweep(1,2,0.6,0.0),  megasprint:_mkSweep(1,9,0.4,0.0),
