      const L1=p1.x-p1.w*1.12, L2=p2.x-p2.w*1.12, R1=p1.x+p1.w*1.12, R2=p2.x+p2.w*1.12;
      const col=dark?'#15161c':'#2e3038';
      if(L1>0||L2>0)poly(0,p1.y,L1,p1.y,L2,p2.y,0,p2.y,col);
      if(R1<vw||R2<vw)poly(R1,p1.y,vw,p1.y,vw,p2.y,R2,p2.y,col);
