      ctx.fillStyle='rgba(255,'+~~(60+70*gp)+',20,'+(0.20+0.18*gp)+')';ctx.fillRect(p2.x-p2.w,p2.y+(p1.y-p2.y)*0.45,p2.w*2,Math.max(1,(p1.y-p2.y)*0.22));
