      for(let k=0;k<8;k++){ const g=_gridSlot(k); if(Math.floor(g.z/SEG_LEN)!==s.index)continue;
        const ws=(s._wScale||1), bx=p1.x+g.x*p1.w/ws, hw=p1.w/ws*0.26, th=Math.max(1,(p1.y-p2.y)*0.6);
        ctx.fillStyle='rgba(240,240,240,0.9)'; ctx.fillRect(bx-hw,p1.y-th,hw*2,th); }
