      const gx=(_l1x+_r1x)*0.5, gw=p1.w*1.45, gh=p1.w*1.30;
      const gcol=ok?'rgba(80,255,150,':'rgba(255,90,90,';
      ctx.save();
      ctx.strokeStyle=gcol+'0.92)';
      ctx.lineWidth=Math.max(2,p1.w*0.09);
      ctx.beginPath();
      ctx.moveTo(gx-gw,p1.y);
