  if(dm._carRoadY==null||!isFinite(dm._carRoadY)){dm._carRoadK=0;dm._carRoadY=null;dm._carScaleK=1;dm._carRoadKSm=null;}
    /* In attract/demo mode the camera is ALWAYS displaced, so _carRoadKSm must start at 1 (fully pinned) and never be allowed to drift down to 0 between shots. */
  if(race&&race.attract&&(dm._carRoadKSm==null||dm._carRoadKSm<1)){
    dm._carRoadKSm=1;
  }
