/* Hidden when the track has no snow, so the layer costs nothing elsewhere. */
/* (1) True only when the GPU layer is present, sized and visible. If any of
   these fail the caller falls through to the CPU renderer, so snow is drawn
   one way or the other — never neither. */
function _gpuSnowLive(){
  try{
    if(!_gpuSnow||!_gpuSnowCv)return false;
    if(_gpuSnowCv.width<2||_gpuSnowCv.height<2)return false;
    if(!_gpuSnowCv.isConnected){
      document.body.appendChild(_gpuSnowCv);   // re-attach if it was removed
    }
    if(_gpuSnowCv.style.display==='none')_gpuSnowCv.style.display='block';
    return true;
  }catch(e){ return false; }
}
