let srWaterRAF=null, srWaterLast=0;
let srWaterFxIdx=0, srWaterFxUntil=0;

function srWaterTick(){
  if(!document.getElementById('_sr_menu')){srWaterRAF=null;return;}
  const now=performance.now();
  const dt=Math.min(0.05,(now-srWaterLast)/1000);
  srWaterLast=now;
  /* Rotate to a new random variation every 10-30 seconds */
  if(now>=srWaterFxUntil){
    let nx=srWaterFxIdx;
    if(SR_WATER_FX.length>1)
      while(nx===srWaterFxIdx)nx=~~(Math.random()*SR_WATER_FX.length);
    srWaterFxIdx=nx;
    srWaterFxUntil=now+10000+Math.random()*20000;
  }
  try{
    const _V0=SR_WATER_FX[srWaterFxIdx]||SR_WATER_FX[0];
    if(window.WaterFX&&window.WaterFX.available())
      window.WaterFX.worldMap(dt*(_V0.sp||1));
    const id=(srFocus===0)?'_sr_prev_r':'_sr_prev_p';
    const pv=document.getElementById(id);
    const wc=document.getElementById('zs-waterfx');
    if(pv&&wc){
      const r=pv.getBoundingClientRect();
      const V=SR_WATER_FX[srWaterFxIdx]||SR_WATER_FX[0];
      wc.style.setProperty('position','fixed','important');
      wc.style.setProperty('left',r.left+'px','important');
      wc.style.setProperty('top',r.top+'px','important');
      wc.style.setProperty('width',r.width+'px','important');
      wc.style.setProperty('height',r.height+'px','important');
      wc.style.borderRadius='6px';
      wc.style.zIndex='2000011';
      wc.style.display='block';
      wc.style.visibility='visible';
      wc.style.pointerEvents='none';
      /* Same as the GP tick: fit() every frame, after the CSS is applied. */
      window.WaterFX.fit();
      /* Variation styling — smooth 1.5s crossfade between looks */
      if(wc._zsFx!==V.n||wc._zsFx===undefined){
        wc._zsFx=V.n;
        wc.style.filter=V.f;
        wc.style.mixBlendMode=V.b;
        wc.style.opacity=String(V.o);
        wc.style.transition='filter 1.5s linear, opacity 1.5s linear';
      }
    }
  }catch(e){}
  srWaterRAF=requestAnimationFrame(srWaterTick);
}
let srEdit=false, srEditRow=0, srOverrides=null;
let srBiome=0, srWeather=0;

const SR_BIOMES=['auto'].concat(BIOME_LIST);   // 'auto' + all 20 biomes
const SR_BIOME_COL={auto:'#7f8fa0',
  plains:'#6a9a4a', ocean:'#2a6a9a', forest:'#2a6a3a', islands:'#3a9a8a',
  arctic:'#c0d8e8', desert:'#c8a860', swamp:'#5a6a3a', volcano:'#8a3020',
  canyon:'#a06840', lunar:'#606068', city:'#7a8a9a', haunted:'#5a3a7a',
  alpine:'#8ab0c8', tundra:'#90a0a8', jungle:'#1a7a3a', savanna:'#b09050',
  mesa:'#9a5838',   glacier:'#a8d0e8', wetland:'#4a8a7a', neon:'#c040d0'};
const SR_WEATHER=['clear','rain','snow','sand','fog'];
const SR_WEATHER_COL={clear:'#7fd0ff',rain:'#4a7ab0',snow:'#e0f0ff',
  sand:'#c8a060',fog:'#909aa4'};

/* Extra controls shown in the RANDOM tile's right-hand column. */
const SR_EXTRA=[
  {k:'__biome',   label:'Biome',      kind:'list', list:SR_BIOMES},
  {k:'__weather', label:'Weather',    kind:'list', list:SR_WEATHER},
  {k:'vegetationMix', label:'Vegetation', min:0, max:3, step:0.05},
  /* max raised 4 -> 10 to match the range the algo tool and the theme
     presets already use (several ship values of 6.0-7.0). */
  {k:'propDensity',   label:'Buildings',  min:0, max:10, step:0.05},
  {k:'skylineScale',  label:'Skyline',    min:0, max:3, step:0.05},
  {k:'_fogDensity',   label:'Fog',        min:0, max:2, step:0.05},
];

/* Strip internal prefixes for display. */
function srLabel(k){
  return k.replace(/^_feat_/,'').replace(/^_/,'');
}

/* Build a full parameter set for a seed (random tile) or preset index. */
function srBuildParams(mode){
  const o={};
  if(mode===0){
    let s=srRandSeed>>>0;
    const rnd=()=>{s^=s<<13;s^=s>>17;s^=s<<5;return (s>>>0)/4294967296;};
    for(let i=0;i<ALGO_PARAMS.length;i++){
      const p=ALGO_PARAMS[i];
      o[p.k]=+(p.min+rnd()*(p.max-p.min)).toFixed(3);
    }
    /* Apply live edits made in edit mode */
    if(srOverrides)for(const k in srOverrides)o[k]=srOverrides[k];
    /* Biome / weather forcing */
    const bi=SR_BIOMES[srBiome];
    if(bi&&bi!=='auto')o._forceBiome=bi;
    const wx=SR_WEATHER[srWeather];
    if(wx==='rain'){o._rainOdds=1;o._snowOdds=0;o._sandOdds=0;}
    else if(wx==='snow'){o._snowOdds=1;o._rainOdds=0;o._sandOdds=0;}
    else if(wx==='sand'){o._sandOdds=1;o._rainOdds=0;o._snowOdds=0;}
    else if(wx==='fog'){o._fogOdds=1;o._fogDensity=Math.max(1.2,o._fogDensity||1.2);}
    else {o._rainOdds=0;o._snowOdds=0;o._sandOdds=0;}
  } else {
    for(let i=0;i<ALGO_PARAMS.length;i++){
      const p=ALGO_PARAMS[i];
      o[p.k]=(p.def!=null)?p.def:+((p.min+p.max)/2).toFixed(3);
    }
    const pr=ALGO_PRESETS[srPresetIdx];
    if(pr&&pr.v)for(const k in pr.v)o[k]=pr.v[k];
  }
  return o;
}

/* All editable rows in the RANDOM tile: parameters + the extra controls. */
const SR_COL_ORDER=[['Geometry','Track Shape','Pacing'],['Features','Safety','Engine'],
                    ['Visuals','Effects','Mechanics']];
function srEditRows(){
  const rows=[];
  for(let ci=0;ci<SR_COL_ORDER.length;ci++)
    for(let si=0;si<SR_COL_ORDER[ci].length;si++){
      const sec=SR_COL_ORDER[ci][si];
      for(let i=0;i<ALGO_PARAMS.length;i++)
        if(ALGO_PARAMS[i].sec===sec)rows.push(ALGO_PARAMS[i]);
    }
  for(let i=0;i<SR_EXTRA.length;i++)rows.push(SR_EXTRA[i]);
  return rows;
}

function srRenderTiles(){
  /* Column order requested: Geometry / Pacing / Safety stacked in col 1,
     Features in col 2, Visuals / Effects / Mechanics stacked in col 3. */
  const COLS=SR_COL_ORDER;
  const secCol={Geometry:'#7fd0ff','Track Shape':'#9ae6ff',Pacing:'#ffd23a',Engine:'#6af0ff',
    Features:'#a6ffc8',Visuals:'#ff9ad0',Safety:'#ff8a6a',Effects:'#c0a0ff',
    Mechanics:'#8fe8b0'};

  function paramsHTML(vals,editable){
    const rows=editable?srEditRows():null;
    let h='<div class="sr-cols">';
    for(let ci=0;ci<COLS.length;ci++){
      h+='<div class="sr-col">';
      for(let si=0;si<COLS[ci].length;si++){
        const sec=COLS[ci][si];
        const list=ALGO_PARAMS.filter(p=>p.sec===sec);
        if(!list.length)continue;
        h+='<div class="sr-psec"><div class="sr-psec-t" style="color:'+
           (secCol[sec]||'#8fd6ff')+'">'+sec.toUpperCase()+'</div>';
        for(let ri=0;ri<list.length;ri++){
          const p=list[ri];
          const v=vals[p.k];
          if(v==null)continue;
          const pct=Math.max(0,Math.min(1,(v-p.min)/Math.max(0.0001,p.max-p.min)));
          /* Floor the bar at 6% so a parameter sitting at its minimum still shows a visible stub — a 0%-wide bar rendered as nothing at all, which is why bridge  */
          const barPct=Math.max(6,pct*100);
          const isSel=editable&&srEdit&&rows[srEditRow]&&rows[srEditRow].k===p.k;
          h+='<div class="sr-prow'+(isSel?' sr-sel':'')+'">'+
             '<span class="sr-pk">'+srLabel(p.k)+'</span>'+
             '<span class="sr-pbar"><i style="width:'+barPct.toFixed(0)+'%;'+
             'background:'+(secCol[sec]||'#8fd6ff')+'"></i></span>'+
             '<span class="sr-pv">'+(+v).toFixed(2)+'</span></div>';
        }
        h+='</div>';
      }
      h+='</div>';
    }
    return h+'</div>';
  }

  /* Right-hand extras column — only on the RANDOM tile */
  function extrasHTML(vals){
    const rows=srEditRows();
    let h='<div class="sr-extras">';
    h+='<div class="sr-psec-t" style="color:#ffd23a">TRACK SETUP</div>';
    h+='<div class="sr-seed">SEED '+(srRandSeed>>>0)+'</div>';
    try{ const _M=_pmModel(); if(_M.conf){ const _f=seedFit(srRandSeed>>>0,vals);
      h+='<div class="sr-seed" style="color:'+(_f>=0.6?'#a6ffc8':_f<=0.4?'#ff8a6a':'#ffd23a')+'">FIT '+Math.round(_f*100)+'%</div>'; } }catch(e){}
    for(let i=0;i<SR_EXTRA.length;i++){
      const e=SR_EXTRA[i];
      const isSel=srEdit&&rows[srEditRow]&&rows[srEditRow].k===e.k;
      if(e.kind==='list'){
        const idx=(e.k==='__biome')?srBiome:srWeather;
        const name=e.list[idx];
        const col=(e.k==='__biome')?SR_BIOME_COL[name]:SR_WEATHER_COL[name];
        h+='<div class="sr-erow'+(isSel?' sr-sel':'')+'">'+
           '<span class="sr-ek">'+e.label+'</span>'+
           '<span class="sr-swatch" style="background:'+col+'"></span>'+
           '<span class="sr-ev">'+name.toUpperCase()+'</span></div>';
      } else {
        const v=vals[e.k]!=null?vals[e.k]:0;
        const pct=Math.max(0,Math.min(1,(v-e.min)/Math.max(0.0001,e.max-e.min)));
        const ebar=Math.max(6,pct*100);
        h+='<div class="sr-erow'+(isSel?' sr-sel':'')+'">'+
           '<span class="sr-ek">'+e.label+'</span>'+
           '<span class="sr-pbar"><i style="width:'+ebar.toFixed(0)+'%;'+
           'background:#ffd23a"></i></span>'+
           '<span class="sr-ev">'+(+v).toFixed(2)+'</span></div>';
      }
    }
    /* Visual preview square — shows the biome's sky/floor/veg palette */
    const _bn=SR_BIOMES[srBiome];
    const _bd=(_bn!=='auto'&&BIOME_DEFS[_bn])?BIOME_DEFS[_bn]:null;
    h+='<div class="sr-visbox" id="_sr_visbox">'+
       '<div class="sr-vis-t">VISUALS</div>'+
       '<canvas id="_sr_vis" width="120" height="80"></canvas>'+
       '<div class="sr-vis-name">'+_bn.toUpperCase()+'</div>'+
       '</div>';
    h+='<div class="sr-editnote">'+(srEdit
      ?'\u25b2\u25bc ROW \u00b7 \u25c0\u25b6 VALUE \u00b7 X EXIT'
      :'X = EDIT MODE')+'</div>';
    return h+'</div>';
  }

  const rv=srBuildParams(0);
  const rEl=document.getElementById('_sr_rand');
  if(rEl){
    rEl.className='sr-bigtile'+(srFocus===0?' sr-focus':'')+(srEdit?' sr-editing':'');
    rEl.innerHTML='<div class="sr-tile-head">'+
      '<span class="sr-tile-label">'+(srEdit?'EDIT MODE':'RANDOM TRACK')+'</span>'+
      '<span class="sr-tile-num">'+(srEdit?'X = EXIT':'')+'</span></div>'+
      '<div class="sr-tile-body">'+
        '<canvas class="sr-prev" id="_sr_prev_r" width="240" height="180"></canvas>'+
        paramsHTML(rv,true)+
        extrasHTML(rv)+
      '</div>';
    _srCachedVals[0]=rv;   // cache for launch parity
    srQueuePreview('_sr_prev_r',srRandSeed>>>0,rv);
    srDrawVisBox(rv);
  }

  const pr=ALGO_PRESETS[srPresetIdx]||{name:'?',desc:'',col:'#888'};
  const pv=srBuildParams(1);
  _srCachedVals[1]=pv;   // cache for launch parity
  const pEl=document.getElementById('_sr_preset');
  if(pEl){
    pEl.className='sr-bigtile sr-preset'+(srFocus===1?' sr-focus':'');
    pEl.innerHTML='<div class="sr-preset-heading">PRESET</div>'+
      '<div class="sr-tile-head">'+
      '<span class="sr-tile-label" style="color:'+pr.col+'">'+pr.name+'</span>'+
      '<span class="sr-tile-num">'+(srPresetIdx+1)+' / '+ALGO_PRESETS.length+'</span></div>'+
      '<div class="sr-preset-desc">'+(pr.desc||'')+'</div>'+
      '<div class="sr-tile-body sr-preset-body">'+
        '<canvas class="sr-prev" id="_sr_prev_p" width="240" height="180"></canvas>'+
      '</div>';   // side-by-side layout: title, description and preview only
    srQueuePreview('_sr_prev_p',(srPresetIdx*2654435761+7919)>>>0,pv);
  }

  const hEl=document.getElementById('_sr_hint');
  if(hEl)hEl.innerHTML=srEdit
    ?'\u25b2\u25bc ROW &nbsp;\u00b7&nbsp; \u25c0\u25b6 VALUE &nbsp;\u00b7&nbsp; X EXIT EDIT &nbsp;\u00b7&nbsp; A RACE'
    :'\u25b2\u25bc SELECT TILE &nbsp;\u00b7&nbsp; \u25c0\u25b6 CHANGE &nbsp;\u00b7&nbsp; X EDIT &nbsp;\u00b7&nbsp; A RACE &nbsp;\u00b7&nbsp; B CLOSE';
  /* Keep the selected edit row visible now that columns scroll. */
  try{ const _sel=document.querySelector('#_sr_rand .sr-sel'); if(_sel&&_sel.scrollIntoView)_sel.scrollIntoView({block:'nearest'}); }catch(e){}
}

/* Adjust the currently selected edit row by dir (-1 or +1). */
function srEditAdjust(dir){
  const rows=srEditRows();
  const r=rows[srEditRow];
  if(!r)return;
  if(r.k==='__biome'){srBiome=(srBiome+dir+SR_BIOMES.length)%SR_BIOMES.length;return;}
  if(r.k==='__weather'){srWeather=(srWeather+dir+SR_WEATHER.length)%SR_WEATHER.length;return;}
  if(!srOverrides)srOverrides={};
  const cur=srBuildParams(0)[r.k];
  const step=r.step||((r.max-r.min)/40);
  let nv=(cur!=null?cur:r.min)+dir*step;
  nv=Math.max(r.min,Math.min(r.max,nv));
  srOverrides[r.k]=+nv.toFixed(3);
}
/* buildTrack() is expensive (thousands of segments), so previews are debounced: a rapid run of d-pad presses only triggers one rebuild once the input  */
const _srPvTimers={}, _srPvKey={}, _srPvDone={}, _srPvImg={};
/* Set by the arrow-key / d-pad navigation handlers. When true the next
   preview is rendered SYNCHRONOUSLY instead of on the 180ms debounce, so
   the tile can never be showing one track while another is launched. */
let _srPvImmediate=false;
function srQueuePreview(canvasId,seed,vals){
  /* The learned like/trash profiles steer generation (trashPick), so they are
     part of what a preview depends on. Keyed on seed+params alone, a preview
     cached before the player liked or trashed a course was reused afterwards
     from the random tile's history — showing a course that no longer loads. */
  let _prof='';
  try{ const L=likeGetProfile(), T=trashGetProfile(); _prof=(L.n|0)+'.'+(L.paramN|0)+'/'+(T.n|0)+'.'+(T.paramN|0); }catch(e){}
  const key=(seed>>>0)+'|'+JSON.stringify(vals)+'|'+_prof;
  const cv=document.getElementById(canvasId);
  const same=(_srPvKey[canvasId]===key);

  /* ═══ ALWAYS RE-BLIT FIRST srRenderTiles() rebuilds the tile's innerHTML on EVERY render, which destroys and recreates the canvas element — it comes  */
  /* Only re-blit the cached image when it belongs to THIS key. Showing the
     previous track's image under a new seed is what made the random tile
     "not load the track in the preview": the preview was debounced by 180ms
     and deliberately kept the old picture up meanwhile, so pressing an arrow
     and confirming quickly launched the new seed while the window still
     showed the old track. A stale image is now discarded, never displayed. */
  const cached=(_srPvKey[canvasId]===key)?_srPvImg[canvasId]:null;
  if(_srPvKey[canvasId]!==key)_srPvImg[canvasId]=null;
  if(cv&&cached){ try{ cv.getContext('2d').putImageData(cached,0,0); }catch(e){} }

  /* Nothing changed — the re-blit above is all that was needed. */
  if(same&&_srPvDone[canvasId])return;

  /* Key changed: keep showing the stale image while the new one builds
     rather than blanking to a placeholder. Only paint the placeholder when
     there is genuinely nothing cached yet. */
  if(cv&&!cached){
    const c=cv.getContext('2d');
    c.fillStyle='#08101e';c.fillRect(0,0,cv.width,cv.height);
    c.fillStyle='#4a7a9a';c.font='10px monospace';c.textAlign='center';
    c.fillText('GENERATING\u2026',cv.width/2,cv.height/2);
  }
  _srPvKey[canvasId]=key;
  _srPvDone[canvasId]=false;
  if(_srPvTimers[canvasId])clearTimeout(_srPvTimers[canvasId]);
  /* Navigation: draw right now so what is on screen is always what will
     launch, even if the player confirms immediately. */
  if(_srPvImmediate){
    _srPvImmediate=false;
    _srPvTimers[canvasId]=null;
    try{
      srDrawPreview(canvasId,seed,vals);
      _srPvDone[canvasId]=true;
      const c3=document.getElementById(canvasId);
      if(c3)_srPvImg[canvasId]=c3.getContext('2d').getImageData(0,0,c3.width,c3.height);
    }catch(e){}
    return;
  }
  _srPvTimers[canvasId]=setTimeout(function(){
    _srPvTimers[canvasId]=null;
    if(!document.getElementById('_sr_menu'))return;
    if(_srPvKey[canvasId]!==key)return;
    srDrawPreview(canvasId,seed,vals);
    _srPvDone[canvasId]=true;
    try{
      const c2=document.getElementById(canvasId);
      if(c2)_srPvImg[canvasId]=c2.getContext('2d')
        .getImageData(0,0,c2.width,c2.height);
    }catch(e){}
  },180);
}

function srDrawPreview(canvasId,seed,vals){
  // Never rebuild during an active race — the preview's restore-buildTrack
  // would overwrite the live segments with the old track.
  if(dm.active)return;
  const cv=document.getElementById(canvasId);
  if(!cv)return;
  const c=cv.getContext('2d');
  const W=cv.width,H=cv.height;
  c.clearRect(0,0,W,H);
  c.fillStyle='#08101e';c.fillRect(0,0,W,H);
  c.strokeStyle='rgba(60,90,130,0.15)';c.lineWidth=1;
  for(let gx=0;gx<=W;gx+=W/6){c.beginPath();c.moveTo(gx,0);c.lineTo(gx,H);c.stroke();}
  for(let gy=0;gy<=H;gy+=H/5){c.beginPath();c.moveTo(0,gy);c.lineTo(W,gy);c.stroke();}

  let pts=null;
  try{
    /* buildTrack() reads MORE than _algoOverride: _wtSettlement and _wtRace persist
       from a previous World Tour race and silently alter generation.
       ALSO: buildTrack() branches on theme.biome (city/neon/lunar urban-density
       multipliers at line ~4219), consuming the RNG differently per biome.
       start() always sets theme=makeTheme(seed) before buildTrack — the preview
       must do the same or the track layout diverges from the one that actually loads. */
    const keepSeed=dm.seed;
    const keepOvr=dm._algoOverride;
    const keepSet=dm._wtSettlement, keepWt=dm._wtRace;
    const keepTheme=theme;                         // save current theme
    const keepSrRand=dm._srRandomTileActive;
    /* Build exactly as the launched race will: never as a demo. dm.demo is
       not cleared by exit(), and demo mode forces the collapsing-road feature
       on (an extra roll that shifts everything generated after it), so a
       preview drawn after the attract demo had run showed a different course
       from the one that loaded. */
    const keepDemo=dm.demo;
    dm.demo=false;
    /* Only the RANDOM tile ('_sr_prev_r') gets the probabilistic canonical-
       angle special modes — the PRESET tile always uses its hand-picked
       parameters and should stay fully predictable. Setting this identically
       here and in srLaunch (same seed, same position in the seeded RNG
       sequence) guarantees the preview and the launched race always agree
       on which special mode (if any) applies. */
    dm._srRandomTileActive=(canvasId==='_sr_prev_r');
    dm._algoOverride=vals;
    dm._wtSettlement=null; dm._wtRace=null;
    dm._forceVariety=null;
    theme=makeTheme(seed>>>0);                     // match what start() does
    buildTrack(seed>>>0);
    pts=mapPts.map(p=>[p[0],p[1],p[2]||0,p[3]||0]);
    dm._algoOverride=keepOvr;
    dm._wtSettlement=keepSet; dm._wtRace=keepWt;
    dm._srRandomTileActive=keepSrRand;
    dm.demo=keepDemo;
    if(!dm.active&&keepSeed!=null&&keepSeed!==(seed>>>0)){
      theme=makeTheme(keepSeed>>>0);               // restore theme for rebuilt track
      buildTrack(keepSeed>>>0);
    } else {
      theme=keepTheme;                             // restore previous theme unchanged
    }
  }catch(e){ pts=null; }

  if(!pts||pts.length<4){
    c.fillStyle='#3a5a70';c.font='11px monospace';c.textAlign='center';
    c.fillText('PREVIEW UNAVAILABLE',W/2,H/2);
    return;
  }

  let mnx=1e9,mxx=-1e9,mny=1e9,mxy=-1e9;
  for(const p of pts){mnx=Math.min(mnx,p[0]);mxx=Math.max(mxx,p[0]);
    mny=Math.min(mny,p[1]);mxy=Math.max(mxy,p[1]);}
  const pad=14;
  const sc=Math.min((W-pad*2)/Math.max(0.001,mxx-mnx),
                    (H-pad*2)/Math.max(0.001,mxy-mny));
  const ox=pad+((W-pad*2)-(mxx-mnx)*sc)*0.5;
  const oy=pad+((H-pad*2)-(mxy-mny)*sc)*0.5;
  const X=(p)=>ox+(p[0]-mnx)*sc, Y=(p)=>oy+(p[1]-mny)*sc;

  const eb=vals.elevBias!=null?vals.elevBias:3.0;
  /* Shadow underlay */
  c.strokeStyle='rgba(0,40,90,0.55)';
  c.lineWidth=Math.max(3,5+eb*0.25);
  c.beginPath();
  pts.forEach((p,i)=>{i?c.lineTo(X(p)+1,Y(p)+1):c.moveTo(X(p)+1,Y(p)+1);});
  c.closePath();c.stroke();
  /* Main ribbon */
  c.strokeStyle='#9fe8ff';
  c.lineWidth=Math.max(2,3+eb*0.15);
  c.beginPath();
  pts.forEach((p,i)=>{i?c.lineTo(X(p),Y(p)):c.moveTo(X(p),Y(p));});
  c.closePath();c.stroke();
  /* ═══ SPLIT-AND-REJOIN ROADS, VISIBLE IN THE PREVIEW
     A fork keeps the same centre line, so the single ribbon never showed it.
     Along each fork the ribbon is cut out and two branch lines are drawn to
     either side, spreading apart with the island's width and rejoining at its
     ends; tracks with forks also get a small "M" badge. */
  const _hasFork=pts.some(p=>(p[2]||0)>0.05);
  if(_hasFork){
    const n=pts.length, spread=Math.max(3.5,Math.min(W,H)*0.028);
    const perp=(i)=>{ const a=pts[(i-1+n)%n], b=pts[(i+1)%n]; let dx=X(b)-X(a), dy=Y(b)-Y(a); const L=Math.hypot(dx,dy)||1; return [-dy/L,dx/L]; };
    const runs=[]; let st=-1;
    for(let i=0;i<=n;i++){ const f=i<n?(pts[i][2]||0):0; if(f>0.05&&st<0)st=i; else if(f<=0.05&&st>=0){ runs.push([Math.max(0,st-1),Math.min(n-1,i)]); st=-1; } }
    for(const [a,b] of runs){
      // cut the ribbon out along the fork (the island)
      c.save(); c.globalCompositeOperation='destination-out'; c.lineCap='round';
      c.lineWidth=Math.max(2,spread*1.1); c.beginPath();
      for(let i=a+1;i<b;i++){ const x=X(pts[i]), y=Y(pts[i]); i===a+1?c.moveTo(x,y):c.lineTo(x,y); }
      c.stroke(); c.restore();
      // two branches that spread with the island and rejoin at the ends
      for(const side of [-1,1]){
        c.strokeStyle='#ffd36a'; c.lineWidth=Math.max(1.5,2+eb*0.08); c.beginPath();
        for(let i=a;i<=b;i++){ const f=Math.min(1,(pts[i][2]||0)/1.15), pp=perp(i), o=side*spread*f;
          const x=X(pts[i])+pp[0]*o, y=Y(pts[i])+pp[1]*o; i===a?c.moveTo(x,y):c.lineTo(x,y); }
        c.stroke();
      }
    }
    // tiny "M" badge, bottom-right
    const bs=Math.max(11,Math.round(Math.min(W,H)*0.075));
    c.fillStyle='rgba(8,16,28,0.85)'; c.fillRect(W-bs-5,H-bs-5,bs,bs);
    c.strokeStyle='#ffd36a'; c.lineWidth=1; c.strokeRect(W-bs-5+0.5,H-bs-5+0.5,bs-1,bs-1);
    c.fillStyle='#ffd36a'; c.font='bold '+Math.round(bs*0.72)+'px monospace'; c.textAlign='center'; c.textBaseline='middle';
    c.fillText('M',W-5-bs/2,H-5-bs/2+1);
    c.textAlign='left'; c.textBaseline='alphabetic';
  }
  /* ═══ MULTI-TIERED OVERPASSES IN THE PREVIEW
     Overpass zones share the centre line too, so each is drawn with a thin
     parallel line alongside (the lower road, on its side) in violet; tracks
     with overpasses get a small "O" badge in the bottom-left corner. */
  const _hasTier=pts.some(p=>p[3]>=2);
  if(_hasTier){
    /* ═══ OVERPASSES DRAWN AS REAL CROSSINGS (like a road map): the lower
       pass is cut with a small gap where it goes under, and the upper pass is
       redrawn continuously across the gap with violet bridge edges, so the
       track visibly crosses OVER ITSELF at each overpass. */
    const n=pts.length, rw=Math.max(3,5+eb*0.25), gapW=rw*1.9;   // rw = the track ribbon's own width
    const runs=(code)=>{ const out=[]; let st=-1; for(let i=0;i<=n;i++){ const on=i<n&&pts[i][3]===code; if(on&&st<0)st=i; else if(!on&&st>=0){ out.push([Math.max(0,st-1),Math.min(n-1,i)]); st=-1; } } return out; };
    // 1) gap in the lower pass
    c.save(); c.globalCompositeOperation='destination-out'; c.lineCap='butt'; c.lineWidth=gapW;
    for(const [a1,b1] of runs(3)){ c.beginPath(); for(let i=a1;i<=b1;i++){ const x=X(pts[i]),y=Y(pts[i]); i===a1?c.moveTo(x,y):c.lineTo(x,y); } c.stroke(); }
    c.restore();
    // 2) the upper pass across it: violet bridge edges, then the road on top
    for(const [a1,b1] of runs(2)){
      const path=()=>{ c.beginPath(); for(let i=a1;i<=b1;i++){ const x=X(pts[i]),y=Y(pts[i]); i===a1?c.moveTo(x,y):c.lineTo(x,y); } };
      c.lineCap='round';
      c.strokeStyle='#c79bff'; c.lineWidth=rw*2.0; path(); c.stroke();
      c.strokeStyle='#0a1420'; c.lineWidth=rw*1.45; path(); c.stroke();
      c.strokeStyle='#9fe6ff'; c.lineWidth=rw*1.0; path(); c.stroke();
    }
    const bs=Math.max(11,Math.round(Math.min(W,H)*0.075));
    c.fillStyle='rgba(8,16,28,0.85)'; c.fillRect(5,H-bs-5,bs,bs);
    c.strokeStyle='#c79bff'; c.lineWidth=1; c.strokeRect(5.5,H-bs-5+0.5,bs-1,bs-1);
    c.fillStyle='#c79bff'; c.font='bold '+Math.round(bs*0.72)+'px monospace'; c.textAlign='center'; c.textBaseline='middle';
    c.fillText('O',5+bs/2,H-5-bs/2+1);
    c.textAlign='left'; c.textBaseline='alphabetic';
  }
  /* Start/finish checker */
  const p0=pts[0];
  for(let a=0;a<2;a++)for(let b=0;b<2;b++){
    c.fillStyle=(a+b)%2?'#ffffff':'#000000';
    c.fillRect(X(p0)-4+a*4,Y(p0)-4+b*4,4,4);
  }
}

/* Draw a small biome/colour-scheme preview: sky gradient, horizon, floor
   bands and a vegetation swatch, using the selected biome's hue triple. */
function srDrawVisBox(vals){
  const cv=document.getElementById('_sr_vis');
  if(!cv)return;
  const c=cv.getContext('2d'),W=cv.width,H=cv.height;
  /* Fully opaque base — the canvas is cleared to transparent on every
     innerHTML rebuild, so an explicit solid fill is required first. */
  c.globalAlpha=1;
  c.globalCompositeOperation='source-over';
  c.clearRect(0,0,W,H);
  c.fillStyle='#0a1420';c.fillRect(0,0,W,H);
  c.fillStyle='#0a1420';c.fillRect(0,0,W,H);
  const bn=SR_BIOMES[srBiome];
  const bd=(bn!=='auto'&&BIOME_DEFS[bn])?BIOME_DEFS[bn]:BIOME_DEFS.plains;
  const sky=bd.sky, flr=bd.floor, vg=bd.veg;
  /* Sky gradient */
  const g=c.createLinearGradient(0,0,0,H*0.55);
  g.addColorStop(0,'hsl('+sky+',55%,42%)');
  g.addColorStop(1,'hsl('+((sky+18)%360)+',48%,62%)');
  c.fillStyle=g;c.fillRect(0,0,W,H*0.55);
  /* Cloud hint */
  c.fillStyle='rgba(255,255,255,'+(0.10+bd.clouds*0.25).toFixed(2)+')';
  c.fillRect(0,H*0.16,W,H*0.05);
  c.fillRect(0,H*0.30,W*0.7,H*0.04);
  /* Floor bands */
  for(let i=0;i<7;i++){
    c.fillStyle='hsl('+flr+','+(30+i*2)+'%,'+(20+(i%2)*7)+'%)';
    c.fillRect(0,H*0.55+i*(H*0.45/7),W,H*0.45/7+1);
  }
  /* Road strip */
  c.fillStyle='hsl('+((flr+180)%360)+',12%,26%)';
  c.beginPath();
  c.moveTo(W*0.44,H*0.55);c.lineTo(W*0.56,H*0.55);
  c.lineTo(W*0.86,H);c.lineTo(W*0.14,H);c.closePath();c.fill();
  /* Vegetation swatch blobs */
  c.fillStyle='hsl('+vg+',48%,30%)';
  for(let i=0;i<5;i++){
    const x=(i%2?W*0.90:W*0.10)+(i*3-6);
    const y=H*0.60+i*(H*0.075);
    c.beginPath();c.ellipse(x,y,5,4,0,0,Math.PI*2);c.fill();
  }
  /* Weather tint */
  const wx=SR_WEATHER[srWeather];
  if(wx==='rain'){c.fillStyle='rgba(60,110,170,0.22)';c.fillRect(0,0,W,H);}
  else if(wx==='snow'){c.fillStyle='rgba(230,245,255,0.22)';c.fillRect(0,0,W,H);}
  else if(wx==='sand'){c.fillStyle='rgba(200,160,90,0.24)';c.fillRect(0,0,W,H);}
  else if(wx==='fog'){c.fillStyle='rgba(150,160,170,0.30)';c.fillRect(0,0,W,H);}
  c.globalAlpha=1;
  c.strokeStyle='rgba(120,180,220,0.45)';c.lineWidth=1;
  c.strokeRect(0.5,0.5,W-1,H-1);
}

/* Launch a race with the chosen tile's parameters. */
var _srCachedVals=[null,null]; // [random, preset] — exact params the preview used
function srLaunch(mode){
  // Use the CACHED params from the preview, not freshly generated ones.
  // This guarantees the launched track matches the previewed one exactly.
  const vals=_srCachedVals[mode]||srBuildParams(mode);
  const seed=(mode===0)?(srRandSeed>>>0):((srPresetIdx*2654435761+7919)>>>0);
  /* Cancel any pending debounced preview so it cannot rebuild a different
     track over the top of the one we are about to start. */
  try{ for(const k in _srPvTimers){ if(_srPvTimers[k])clearTimeout(_srPvTimers[k]); } }catch(e){}
  /* ═══ EXACT PREVIEW PARITY srDrawPreview builds with: _algoOverride = vals, _wtSettlement = null, _wtRace = null. */
  const _frozen=JSON.parse(JSON.stringify(vals));
  try{ dm._algoOverride=_frozen; }catch(e){}
  try{ dm._wtSettlement=null; dm._wtRace=null; }catch(e){}
  try{ if(window.ZS_stopDemoTimers)window.ZS_stopDemoTimers(); }catch(e){}
  srClose();
  start(seed,{fromSR:true,algo:_frozen,srRandomTile:(mode===0)});
  /* srClose() above re-armed the attract-demo scheduler (it assumes the menu
     is closing back to the title). Twelve seconds later that raised the title
     screen over the running race. The player is racing now — disarm it. */
  try{ if(window.ZS_stopDemoTimers)window.ZS_stopDemoTimers(); }catch(e){}
  /* FORCE rebuild with the exact frozen params — guarantees the race track
     matches the preview regardless of what start() did internally. The second
     buildTrack is cheap (~8ms) and eliminates every possible mismatch path. */
  try{
    dm._algoOverride=_frozen;
    dm._wtSettlement=null; dm._wtRace=null; dm._forceVariety=null;
    dm._srRandomTileActive=(mode===0);
    /* Fresh theme, exactly as the preview builds with. The build writes
       weather onto the theme object (set-pieces), so rebuilding on the theme
       the first build had already modified could yield a different course. */
    theme=makeTheme(seed>>>0);
    buildTrack(seed>>>0);
    resetRace();
  }catch(e){}
  try{
    var _t=document.getElementById('scr-title');
    if(_t){_t.style.zIndex='';_t.classList.remove('active');}
    var _v=document.getElementById('title-veil');
    if(_v)_v.style.display='none';
    document.body.classList.add('in-race');
    document.body.classList.remove('on-title');
  }catch(e){}
}

function srFlipTile(el,entry){
  if(!el)return;
  // (9) THE DISAPPEARING MINIMAP. The first version swapped el.innerHTML
  // The front DOM is now never touched. The back is a separate absolutely
  if(!el._backEl){
    // (4) ONE SOURCE OF TRUTH.
    // so front and back can never contradict: the back is simply the same
    const f=(entry&&entry.features)||{};
    const lbl=(typeof _SR_FEAT_LABELS!=='undefined')?_SR_FEAT_LABELS:{};
    const order=(typeof _SR_FEAT_ORDER!=='undefined')?_SR_FEAT_ORDER:Object.keys(f);
    const pretty=[];
    for(const k of order){
      const cnt=f[k];
      if(cnt>0)pretty.push(cnt+'\u00d7 '+(lbl[k]||k.replace(/_/g,' ')));
    }
    for(const k in f){
      if(f[k]>0&&order.indexOf(k)<0)pretty.push(f[k]+'\u00d7 '+(lbl[k]||k.replace(/_/g,' ')));
    }
    const best=entry&&entry.best!=null?entry.best:null;
    const t=(ms)=>{
      if(ms==null||ms>=180000)return '\u2014';
      const m=Math.floor(ms/60000), sec=((ms%60000)/1000).toFixed(2).padStart(5,'0');
      return m+':'+sec;
    };
    const back=document.createElement('div');
    /* (item 18) Styling lives in race.css under .zs-tile-back. */
    back.className='zs-tile-back';
    back.innerHTML=
      '<div style="color:#7fd;font-size:11px;letter-spacing:1px;margin-bottom:6px">COURSE FEATURES</div>'+
      '<div style="flex:1;overflow:hidden;color:#cde;font-size:10px;line-height:1.5">'+
        (pretty.length
          ? pretty.slice(0,14).map(x=>'\u25b8 '+x).join('<br>')
          : '<span style="color:#568">Standard circuit \u2014 no exotic features</span>')+
        (pretty.length>14?'<br><span style="color:#568">+'+(pretty.length-14)+' more</span>':'')+
      '</div>'+
      '<div style="border-top:1px solid #1d3346;margin-top:6px;padding-top:6px;'+
      'display:flex;justify-content:space-between;font-size:10px">'+
        '<span style="color:#68a">BEST</span><span style="color:#ffd24d">'+t(best)+'</span></div>'+
      (entry&&entry.themeName
        ? '<div style="color:#568;font-size:9px;margin-top:3px">'+entry.themeName+'</div>' : '')+
      // Same badges the front shows, so both faces agree on those too.
      (entry&&entry.isLong?'<div style="color:#ffd23a;font-size:9px">\u2605 EXTENDED +30%</div>':'')+
      (entry&&entry.roadFire?'<div style="color:#ff9a3c;font-size:9px">\ud83d\udd25 FIRE HAZARD</div>':'')+
      (entry&&entry.hasWater?'<div style="color:#5fd8ff;font-size:9px">\ud83c\udf0a WATERSIDE</div>':'')+
      '<div style="color:#456;font-size:9px;margin-top:4px">'+padG('y')+' \u21ba back</div>';
    el.appendChild(back);
    el._backEl=back;
  }
  const showBack=(el._flipped!==true);
  el.style.transition='transform 0.16s ease-in';
  el.style.transform='perspective(600px) rotateY(90deg)';
  setTimeout(()=>{
    el._backEl.style.display=showBack?'flex':'none';
    el._flipped=showBack;
    el.style.transition='transform 0.16s ease-out';
    el.style.transform='perspective(600px) rotateY(0deg)';
  },160);
}
function srHighlight(ov,list){
  // The feature list is now rendered INLINE inside every tile at creation
  // duplicate: that entire bug class no longer has anywhere to occur.
  ov.querySelectorAll('._sr_tile').forEach((t,i)=>{
    const sel=i===srSel;
    t.style.animation=sel?'_srTilePulse 1.6s ease-in-out infinite':'none';
    t.style.borderColor=sel?'#5fcf8a':(list[i]?'#2f7a4f':'#1a1a2a');
    t.style.boxShadow=sel?'':'none';
    if(sel){
      try{t.scrollIntoView({block:'nearest',inline:'nearest'});}catch(e3){}
    }
    if(sel){
      const menu=document.getElementById('_sr_menu');
      if(i<5&&menu){try{menu.scrollTo({top:0,behavior:'smooth'});}catch(e){menu.scrollTop=0;}}
      else if(t.scrollIntoView)try{t.scrollIntoView({behavior:'smooth',block:'nearest'});}catch(e){t.scrollIntoView(false);}
    }
  });
}
function srClose(){
  const ov=document.getElementById('_sr_menu');
  if(ov){
    try{ if(ov._srKeyHandler)window.removeEventListener('keydown',ov._srKeyHandler); }catch(e){}
    try{ if(ov._srStopPoll)ov._srStopPoll(); }catch(e){}
    ov.remove();
  }
  if(srPollIv){clearInterval(srPollIv);srPollIv=null;}
  if(srWaterRAF){cancelAnimationFrame(srWaterRAF);srWaterRAF=null;}
  try{
    if(window.ZS_resetPadEdges)window.ZS_resetPadEdges();
    /* Re-arm the demo scheduler. stopDemoTimers() killed it when the menu
       opened; without this the title screen's B button had nothing to
       advance and appeared dead. */
    if(window.ZS_rearmDemo)window.ZS_rearmDemo();
  }catch(e){}
  try{
    const wc=document.getElementById('zs-waterfx');
    if(wc){
      wc.style.cssText=''; wc.classList.remove('zs-wfx-menu'); wc.classList.add('zs-wfx-off');   // styled in race.css
      wc._zsFx=undefined;
    }
    document.body.classList.remove('zs-sr-water');
    if(window.WaterFX)window.WaterFX.hide();
  }catch(e){}
  musicStop();
  try{document.querySelectorAll('.stream-container,.scroll-up-image').forEach(el=>{el.style.display=el._srPrevDisp||'';});}catch(e){}
}
function srDebugActivate(){
  // Never let a stale flag from a previous SR random-tile interaction leak
  // into this unrelated bulk debug generation.
  dm._srRandomTileActive=false;
  // spawn 36 magic cars + create/save 36 tracks
  try{
    if(typeof CS!=='undefined'&&CS){
      CS._magicCars=CS._magicCars||[];
      const bx=(window._isoState?~~window._isoState.camTX:100),by=(window._isoState?~~window._isoState.camTY:100);
      for(let i=0;i<100;i++){
        CS._magicCars.push({wx:bx+(i%10)*3-14,wy:by+~~(i/10)*3-16,active:true,cargoC:0,cargoI:0,_raceSeed:(1000+i*7919)>>>0});
      }
    }
  }catch(e){}
  // COMPLETELY FRESH SET on every press: 36 brand-new random seeds run
  // counter XOR randomness, so repeated activations can never collide
  let _gen=0;
  try{_gen=(parseInt(localStorage.getItem('zs_sr_gen')||'0',10)||0)+1;
      localStorage.setItem('zs_sr_gen',String(_gen));}catch(e){_gen=(Math.random()*1e6)|0;}
  const base=((Date.now()>>>0)^(_gen*2654435761)^((Math.random()*4294967296)>>>0))>>>0;
  const l=[];
  // 100 seeds — full roster
  const _ARCHS=['SNAKE','OVAL_SPRINT','RALLY','ALPINE','FIGURE_8','STADIUM',
    'SPEEDBOWL','MOUNTAIN_PASS','TWISTER','DEATH_VALLEY','CROSS_CIRCUIT','LOOP_DELUXE',
    'GAUNTLET_RUN','SKY_WEAVE','CHAOS_MIX','PIPE_DREAM','CORKSCREW_ALLEY','JUNCTION_MAZE',
    'DECK_STACK','VELODROME','SERPENTINE','FREEFALL_RUN','TECHNICAL_PARK','GRAND_TOUR'];
  const _STYLES=['POWER_STRIP','SPEED_ARROWS','GAUNTLET','TECHNICAL','BRAWLER','SLINGSHOT','MOMENTUM'];
  const _PROFS=['DEEP_FOREST','RAINFOREST','AUTUMN_WOODS','CHERRY_GROVE','JUNGLE_CANOPY',
    'NEON_FLORA','FROST_PINES','GARDEN_CITY','PARKWAY','ORCHARD_RUN','RIVERSIDE','TERRACED',
    'BOULEVARD','METROPOLIS','DOWNTOWN','INDUSTRIAL','NEON_DISTRICT','WILDERNESS','HIGH_STEPPE',
    'CRYSTAL_WASTE','EMBER_FIELDS'];
  for(let i=0;i<100;i++){
    /* Four candidates per slot, screened by the preference model. */
    const sd=pickPreferredSeed([0,1,2,3].map(k=>((base^(i*2246822519)^Math.imul(k,0x27d4eb2f))>>>0)||1));
    // Co-prime strides guarantee every track hits a distinct combination
    // (12 archetypes × 7 styles × 21 profiles = 1764 combos, no repeats in 100).
    dm._forceVariety={
      arch:_ARCHS[i%_ARCHS.length],
      style:_STYLES[(i*3+((i/_ARCHS.length)|0))%7],
      profile:_PROFS[(i*13+((i/7)|0)*5)%_PROFS.length]
    };
    theme=makeTheme(sd);
    buildTrack(sd);
    const pts=mapPts.filter((_,j)=>j%3===0).map(([x,y])=>[+x.toFixed(3),+y.toFixed(3)]);
    const tod=+((i/100+0.02)%1).toFixed(3);
    const _bd=BIOME_DEFS[theme.biome];
    l.push({seed:sd,best:(_srCarry&&_srCarry[sd]!=null)?_srCarry[sd]:180000,
      pts,name:trackNameForSeed(sd,_bd?_bd.tag:null),tod,
      themeName:theme.trackTheme?theme.trackTheme.name:null,
      features:Object.assign({},dm._lastFeatures),   // feature manifest for preview
      isLong:!!dm._lastIsLong,
      hasWater:!!dm._hasWater,roadFire:!!dm._roadFire,
      arch:dm._forceVariety.arch,
      fv:Object.assign({},dm._forceVariety),   // REQUIRED so racing reproduces it
      date:Date.now()});
  }
  dm._forceVariety=null;   // back to fully-random for normal play
  srStore(l);
  try{localStorage.setItem(SR_UNLOCK,'1');}catch(e){}
  injectTitleButton();
  srOpen();
}
// title-screen entry is a real menu item (tinywar24.html buildTitleItems). drive.
function injectTitleButton(){
  try{
    const ex=document.getElementById('_sr_title_btn');if(ex)ex.remove();  // legacy cleanup
    if(typeof window.renderTmenu==='function'){window.renderTmenu();return true;}
  }catch(e){}
  return false;
}
(function _titleRetry(n){
  if(injectTitleButton()||n<=0)return;
  setTimeout(()=>_titleRetry(n-1),300);
})(20);

// ─── PUBLIC + DEBUG
const _FEAT_ABSURD=['rainbowroad','turbotornado','mirrorstraight','zigzagstorm','megaelevation',
  'cliffdrop','rollerwave','spiralstair','blindsnap','slingshot'];
window.DriveMode={start,exit,get active(){return dm.active;},
  isActive:()=>!!dm.active, setMusicMuted:setMusicMuted, isMusicMuted:()=>_musMuted,
  /* The seed of the race currently loaded. Used by the continue prompt to
     confirm it is acting on the race it was raised for, not a later one. */
  seed:()=>(dm.seed>>>0)||0,
    /* ── SELF-TEST HOOKS (see the harness at the end of debug.js)  Exposed so the suite can assert on generation and tuning without reaching into module scope — which it cannot do, and which is why the previous  */
  buildTrackForTest:(sd)=>{
    if(dm.active)return null;
    try{ buildTrack(sd>>>0); return segments; }catch(e){ return null; }
  },
  /* Culling horizons, for the self-test. Computed from the live constants so
     the assertions cannot pass against stale copies. */
  horizons:()=>{
    const D=DRAW_DIST;
    const at=(q,ds)=>~~(D*Math.max(0.68,ds)*(0.96+0.04*q));
    const best=at(1,1.0), worst=at(0.35,0.45);
    const reach=((dm._lastParams&&dm._lastParams.propReach)||1);
    return {
      best:best, worst:worst,
      spanPct:1-(worst/best),
      propHorizon:Math.round(D*reach),
      /* drawProp fades against dm._propFar and the loop queues to the same
         value, so the last visible prop is always at alpha ~0. */
      fadeMatchesCutoff:true
    };
  },
  /* Demo formation, for the self-test. A high lane/depth correlation means the
     pack is arranged on a diagonal, which reads as single file from behind. */
  demoFormation:()=>{
    const n=Math.max(1,rivals.length||7);
    const ORDER=_laneOrder(n);
    const lanes=[],slots=[];
    for(let id=1;id<=n;id++){
      const sl=ORDER[(id-1)%n]/n;
      lanes.push((sl-0.5+0.5/n)*1.40);
      slots.push((id-1)-(n-1)/2);
    }
    const mean=a=>a.reduce((x,y)=>x+y,0)/a.length;
    const ml=mean(lanes), ms=mean(slots);
    let num=0,dl=0,ds=0;
    for(let i=0;i<n;i++){num+=(lanes[i]-ml)*(slots[i]-ms);dl+=Math.pow(lanes[i]-ml,2);ds+=Math.pow(slots[i]-ms,2);}
    const srt=lanes.slice().sort((a,b)=>a-b);
    let gap=Infinity;
    for(let i=1;i<n;i++)gap=Math.min(gap,srt[i]-srt[i-1]);
    return {corr:Math.abs(num/Math.sqrt(dl*ds||1)), minLaneGap:gap, n:n};
  },
  demoShots:()=>({shots:_DEMO_SHOTS.length,rates:_DEMO_RATE.length}),
  /* QA: render the current frame with the 2D path and with the GPU batch
     and report how far apart they are (engine plan E3). */
  renderCompare:(withImages)=>{ try{
    if(!canvas||!ctx||!P)return null;
    const vw=canvas.width, vh=canvas.height, keep=(typeof window!=='undefined')?window.ZS_GPU_BATCH:undefined;
    const shot=()=>ctx.getImageData(0,0,vw,vh);
    /* Warm both paths first: buildings finish generating over several
       frames and would otherwise read as a difference. */
    for(let w=0;w<6;w++){ window.ZS_GPU_BATCH=(w&1)===0; renderWorld(vw,vh,0); }
    window.ZS_GPU_BATCH=false; renderWorld(vw,vh,0); const A=shot();
    let t0=performance.now(); renderWorld(vw,vh,0); const tA=performance.now()-t0;
    window.ZS_GPU_BATCH=true; GLBatch.reset(); renderWorld(vw,vh,0);
    const f0=GLBatch.stats.flushes; t0=performance.now(); renderWorld(vw,vh,0); const tB=performance.now()-t0;
    const fl=GLBatch.stats.flushes-f0; const B=shot();
    window.ZS_GPU_BATCH=false; renderWorld(vw,vh,0); const C=shot();   // noise baseline: 2D vs 2D
    window.ZS_GPU_BATCH=keep;
    const dif=(X,Y)=>{ let sum=0,big=0; const a=X.data,b=Y.data;
      for(let i=0;i<a.length;i+=4){ const d=(Math.abs(a[i]-b[i])+Math.abs(a[i+1]-b[i+1])+Math.abs(a[i+2]-b[i+2]))/3; sum+=d; if(d>40)big++; }
      return [+(sum/(a.length/4)).toFixed(3),+(big/(a.length/4)*100).toFixed(3)]; };
    const dB=dif(B,C), dN=dif(A,C);
    const o={meanDiff:dB[0],bigPct:dB[1],noiseMean:dN[0],noiseBig:dN[1],ms2d:+tA.toFixed(2),msBatch:+tB.toFixed(2),flushes:fl};
    if(withImages){ const c=document.createElement('canvas'); c.width=vw; c.height=vh; const g=c.getContext('2d');
      g.putImageData(A,0,0); o.imgA=c.toDataURL('image/png'); g.putImageData(B,0,0); o.imgB=c.toDataURL('image/png'); }
    return o;
  }catch(e){ return {error:e.message,stack:String(e.stack).split('\n').slice(0,3).join(' | ')}; } },
  /* Engine status / switches (engine plan). */
  engine:(o)=>{ try{
    if(o&&'batch' in o){ window.ZS_GPU_BATCH=!!o.batch; if(o.batch)GLBatch.reset(); }
    const st=GLBatch.stats;
    return {batch:GLBatch.available(),flushes:st.flushes,frames:st.frames,batched:st.batched,passed:st.passed,
            vertsPerFrame:st.frames?Math.round(st.verts/st.frames):0,flushesPerFrame:st.frames?+(st.flushes/st.frames).toFixed(1):0,
            disabledFor:st.disabledFor||null,gpu:GLBatch.gpu(),calibration:GLBatch.calibration(),
            perf:{worldMs:+_perf.world.toFixed(2),loopMs:+_perf.loop.toFixed(2),frameMs:+(_ftAvg||0).toFixed(2),quality:+(_q||0).toFixed(2),res:_resScale()},
            caps:ENGINE_CAPS,view:_camMode};
  }catch(e){ return {error:e.message}; } },
  /* Preference model (plan part 5). */
  pickSeed:(c)=>pickPreferredSeed(c),
  seedFit:(sd)=>seedFit(sd>>>0),
  prefSummary:()=>prefSummary(),
  /* QA: sample every attract shot over its whole 7-second slot at 60 Hz,
     through the same guard and envelope the renderer applies, and report
     per-axis ranges, non-finite values and the largest single-frame jump
     (a cut is only allowed at the slot boundary). */
  lintShots:()=>{
    const AX=['yaw','zoom','lift','pitch','roll','ztrav','xoff'];
    const rng={}; AX.forEach(a=>rng[a]=[Infinity,-Infinity]);
    const bad=[], jumps=[];
    for(let i=0;i<_DEMO_SHOTS.length;i++){
      let prev=null, worst=0, worstAx='';
      for(let f=0;f<=420;f++){
        const o=_shotPose(i,f/420);
        for(let a=0;a<7;a++){
          const v=o[a];
          if(!isFinite(v)){ bad.push({shot:i,t:+(f/420).toFixed(3),axis:AX[a]}); continue; }
          if(v<rng[AX[a]][0])rng[AX[a]][0]=v; if(v>rng[AX[a]][1])rng[AX[a]][1]=v;
          if(prev){ const d=Math.abs(v-prev[a])/(a===5?40:1); if(d>worst){worst=d;worstAx=AX[a];} }
        }
        prev=o;
      }
      jumps.push({shot:i,maxStep:+worst.toFixed(4),axis:worstAx});
    }
    jumps.sort((a,b)=>b.maxStep-a.maxStep);
    for(const a of AX)rng[a]=rng[a].map(v=>+v.toFixed(3));
    return {shots:_DEMO_SHOTS.length,ranges:rng,nonFinite:bad.slice(0,20),worstSteps:jumps.slice(0,12)};
  },
  backReach:()=>{
    var worst=null;
    for(var i=0;i<_DEMO_SHOTS.length;i++){
      for(var p=0;p<=1;p+=0.05){
        var o=_shotGuard(_DEMO_SHOTS[i](p),p,i);
        var z=o[5]||0, az=Math.abs(o[0]||0);
        if(z<=0)continue;
        var back=Math.min(160,Math.max(Math.round(az*45),Math.max(0,Math.round(z+6))));
        if(back<z&&(worst===null||z-back>worst.deficit))
          worst={shot:i,ztrav:+z.toFixed(1),back:back,deficit:z-back};
      }
    }
    return {worst:worst};
  },
  tuning:()=>({
    boxX:MAGNET.boxX, boxXHard:MAGNET.boxXHard,
    playerCeil:MAX_SPEED*(TURBO_KMH[TURBO_MAX-1]/KMH_SCALE)*GAME_SPEED_MUL,
    rivalCeil :MAX_SPEED*(TURBO_KMH[TURBO_MAX-1]/KMH_SCALE)*GAME_SPEED_MUL,
    contactDmgIsRate:true,
    /* CARS lives in the shell block, not this closure — reading it directly
       threw. Published by the shell on window for exactly this reason. */
    carBudgets:(function(){
      try{ return (window.ZS_cars||[]).map(function(c){
        return c.power+c.speed+c.weight+c.accel; }); }
      catch(e){ return []; }
    })()
  }),
  /* Attract-mode shot clock, reset when the demo starts. Exposed because the
     demo scheduler lives in the shell scope, outside this closure. */
  resetDemoClock:()=>{ _demoClock=0; },
  /* QA: freeze the attract camera on one shot at progress p (0..1), or pass
     null to resume the cycle. Used by the contact-sheet harness. */
  demoPin:(idx,p)=>{ dm._demoPin=(idx==null)?null:{idx:idx|0,p:+p||0}; },
  /* QA: build a seed exactly as start() would (theme first) and return the
     numbers the generation audit tracks: pacing, feature spread, roadside
     coherence. Refuses while a race is live — it replaces the segments. */
  auditTrack:(sd)=>{
    if(dm.active)return null;
    const keepTheme=theme;
    try{
      sd=sd>>>0; theme=makeTheme(sd); buildTrack(sd);
      const N=segments.length, o={seed:sd,segs:N,char:segments._char,arch:dm._lastArch,
        biome:theme.biome,themeName:theme.trackTheme&&theme.trackTheme.name,curve:dm._lastCurve};
      let absC=0,sharp=0,maxRun=0,run=0,yMin=1e9,yMax=-1e9,maxSlope=0;
      for(let i=0;i<N;i++){ const g=segments[i], c=Math.abs(g.curve||0); absC+=c;
        if(c>=3.125){sharp++; run=0;} else { run++; if(run>maxRun)maxRun=run; }
        const y=g.p2.world.y; if(y<yMin)yMin=y; if(y>yMax)yMax=y;
        maxSlope=Math.max(maxSlope,Math.abs(g.p2.world.y-g.p1.world.y)/SEG_LEN); }
      o.meanCurve=+(absC/N).toFixed(3); o.sharpPct=+(sharp/N*100).toFixed(1);
      o.longestMild=maxRun; o.elevRange=Math.round(yMax-yMin); o.maxSlope=+maxSlope.toFixed(2);
      const log=dm._lastFeatLog||[];
      o.features=log.length; o.featureKinds=new Set(log.map(f=>f.k)).size;
      /* Share of feature emissions that land in the last 12% of the lap —
         a high number means the director dumped leftovers at the end. */
      o.tailDump=+(log.filter(f=>f.a>N*0.88).length/Math.max(1,log.length)).toFixed(2);
      /* Roadside coherence, per 150-segment window and side: how many
         distinct tree forms stand together, the hue spread of those trees,
         and buildings with no neighbour within 40 segments (orphans). */
      const W=150; let forms=0,hueSd=0,wins=0,trees=0,blds=0,orph=0,land=0;
      const bldAt={'-1':[],'1':[]};
      const list=(g)=>{const a=[];if(g.sprite)a.push(g.sprite);if(g.sprite2)a.push(g.sprite2);
        if(g.extraVeg)for(const e of g.extraVeg)a.push(e);return a;};
      for(let i=0;i<N;i++)for(const sp of list(segments[i])){
        if(sp.veg==='tree')trees++; else if(sp.veg==='land')land++;
        else if(!sp.veg){blds++; bldAt[sp.side<0?'-1':'1'].push(i);} }
      for(const k in bldAt){ const a=bldAt[k]; for(let j=0;j<a.length;j++){
        const nb=(j>0&&a[j]-a[j-1]<=40)||(j<a.length-1&&a[j+1]-a[j]<=40); if(!nb)orph++; } }
      for(let w0=0;w0+W<=N;w0+=W)for(const sd2 of [-1,1]){
        const fs=new Set(), hs=[];
        for(let i=w0;i<w0+W;i++)for(const sp of list(segments[i])){
          if(sp.veg!=='tree'||sp.side!==sd2)continue;
          fs.add((sp.tf|0)%12); if(sp.hueAbs!=null)hs.push(sp.hueAbs); }
        if(!fs.size)continue;
        wins++; forms+=fs.size;
        if(hs.length>1){ let sx=0,sy=0; for(const h of hs){sx+=Math.cos(h*Math.PI/180);sy+=Math.sin(h*Math.PI/180);}
          const R=Math.sqrt(sx*sx+sy*sy)/hs.length; hueSd+=Math.sqrt(-2*Math.log(Math.max(1e-6,R)))*180/Math.PI; }
      }
      let eco=0; for(let i=0;i<N;i++)if(segments[i]._eco&&segments[i]._eco!==theme.biome)eco++;
      o.ecotonePct=+(eco/N*100).toFixed(1);
      let bk=0,sf=0,vd=0; for(let i=0;i<N;i++){ const g=segments[i]; if(g.bank&&Math.abs(g.bank)>0.2)bk++; if(g.surf)sf++; if(g.voidDeck)vd++; }
      o.bankPct=+(bk/N*100).toFixed(1); o.surfPct=+(sf/N*100).toFixed(1); o.skyPct=+(vd/N*100).toFixed(1);
      o.trees=trees; o.buildings=blds; o.landforms=land; o.env=(segments._env&&segments._env.k.length)||0;
      o.formsPerWindow=+(forms/Math.max(1,wins)).toFixed(2);
      o.treeHueSpread=+(hueSd/Math.max(1,wins)).toFixed(1);
      o.orphanBldPct=+(orph/Math.max(1,blds)*100).toFixed(1);
      o.featLog=log.map(f=>f.k+'@'+(f.a/N).toFixed(2));
      o.featLost=log.filter(f=>f.a>=N).length;          // placed, then cut off the lap
      o.exhausted=dm._lastExhausted||0;                 // appended by the must-place safety net
      o.absurd=log.filter(f=>_FEAT_ABSURD.indexOf(f.k)>=0).length;
      return o;
    }catch(e){ return {seed:sd,error:e.message}; }
    finally{ theme=keepTheme; }
  },
  setSfxMuted:setSfxMuted, isSfxMuted:()=>_sfxMuted,
// ── Standalone-shell API (race.html)  race.
  trackName:(sd)=>{try{const b=BIOME_DEFS[makeTheme(sd>>>0).biome];
    return trackNameForSeed(sd>>>0,b?b.tag:null);}catch(e){return 'COURSE '+((sd>>>0)%9973);}},
  /* Kept for external callers. Modes 0-4 were distances, so they map onto the
     axis; 5 is still the discrete first-person view. */
  setCamera:(m)=>{try{
    const v=(m|0);
    if(v===5){_camMode=5;}
    else{_camMode=0;_camDist=[_CAM_DIST_HOME,0.10,1.0,0.0,0.55][((v%5)+5)%5];}
  }catch(e){}},
  /* (10) Brief banner announcing the handoff to the auto-driver. */
  /* (6) Apply a debug viewpoint. Held on dm so the render honours it in place
     of the stick-driven orbit until cleared. */
  setView:(v)=>{try{
      /* (item 56) Carries all seven camera axes, not three. The cinematic vocabulary gained pitch, roll, Z-traverse and lateral offset, but this bridge still forwarded only az/zoom/lift — so a debug viewpoint could never use  */
    dm._dbgView=v?{az:v.az||0,zoom:v.zoom||1,lift:v.lift||0,
                   pitch:v.pitch||0,roll:v.roll||0,
                   rollRate:v.rollRate||0,
                   ztrav:v.ztrav||0,xoff:v.xoff||0}:null;
  }catch(e){}},
  toast:(t)=>{try{showMsg(t);}catch(e){}},
  notify:(msg,ok)=>{try{showToast(msg,ok!==false);}catch(e){try{showMsg(msg);}catch(e2){}}},
  musicDir:()=>{try{return MUSIC_DIR;}catch(e){return 'music/';}},
  showHandoff:()=>{try{
    dm._handoffUntil=performance.now()+2600;
  }catch(e){}},
    /* (1) PREVIEW MUST MATCH THE RACE. buildTrack() reads dm._algoOverride and dm._wtRace (the World Tour lap and length multipliers) as it generates. */
  minimap:(sd,opts)=>{
    try{
      const keepSeed=dm.seed;
      const keepOvr=dm._algoOverride, keepWt=dm._wtRace;
      if(opts&&'algo' in opts)dm._algoOverride=opts.algo;
      if(opts&&'worldTour' in opts)dm._wtRace=opts.worldTour;
      buildTrack(sd>>>0);
      const pts=mapPts.map(p=>[p[0],p[1]]);
      dm._algoOverride=keepOvr; dm._wtRace=keepWt;
      if(keepSeed!=null&&keepSeed!==sd)buildTrack(keepSeed>>>0);
      return pts;
    }catch(e){return null;}
  },
  camera:()=>{try{return _camMode;}catch(e){return 0;}},
  lapTimes:()=>{try{return {lap:P&&P.lapTimes?P.lapTimes.slice():[],
    best:P?P.bestLap:0, total:(P&&P.finishMs&&race.goMs)?(P.finishMs-race.goMs):0};}
    catch(e){return {lap:[],best:0,total:0};}},
  // Full diagnostic dump for the standalone debug box.
  diag:()=>{
    const o={};
    try{
      o.seed=dm.seed; o.trackName=dm.trackName; o.character=segments._char;
      o.segments=segments.length; o.trackLength=trackLength;
      o.lap=P?P.lap:0; o.laps=LAPS; o.rivals=rivals.length;
      o.speed=P?Math.round(P.speed):0; o.kmh=P?Math.round(P.speed/MAX_SPEED*KMH_SCALE):0;
      o.power=P?+P.power.toFixed(1):0; o.powerCap=P?P.powerCap:0;
      o.x=P?+P.x.toFixed(3):0; o.z=P?Math.round(P.z):0;
      o.turboCharges=P?P.turboCharges:0;
      o.camMode=_camMode; o.orbitAz=+(dm._orbitAz||0).toFixed(3);
      o.orbitZoom=+(dm._orbitZoom||1).toFixed(3); o.pitch=+((P&&P._pitch)||0).toFixed(3);
        /* ── FULL CAMERA STATE — previously only az/zoom/pitch were exported ── All seven orbit axes, the camera distance slider, the projected horizon Y, and the car-pinning weights are now included so the Track Core tile shows  */
      o.orbitLift=+(dm._orbitLift||0).toFixed(3);
      o.orbitPitch=+(dm._orbitPitch||0).toFixed(3);
      o.orbitRoll=+(dm._orbitRoll||0).toFixed(4);
      o.orbitZ=+(dm._orbitZ||0).toFixed(2);
      o.orbitX=+(dm._orbitX||0).toFixed(3);
      o.camDist=+(_camDist!=null?_camDist:0).toFixed(3);
      o.horizonY=dm._horizonY!=null?+dm._horizonY.toFixed(1):null;
      o.dde=dm._dde!=null?dm._dde:null;
      o.ddeSm=typeof _ddeSm==='number'?+_ddeSm.toFixed(1):null;  // FIX 20
      o.propFar=dm._propFar!=null?dm._propFar:null;
      o.shotIdx=dm._lastDemoShot!=null?dm._lastDemoShot:null;
      o.roadTop=dm._roadTopSm!=null?+dm._roadTopSm.toFixed(1):null;
      o.fillTop=dm._fillTopY!=null?+dm._fillTopY.toFixed(1):null;
      o.carRoadK=+(dm._carRoadK||0).toFixed(3);
      o.carRoadY=dm._carRoadY!=null?+dm._carRoadY.toFixed(1):null;
      o.carScaleK=+(dm._carScaleK!=null?dm._carScaleK:1).toFixed(3);
      o.carRoadKSm=+(dm._carRoadKSm!=null?dm._carRoadKSm:0).toFixed(3);
      o.params=Object.assign({},dm._lastParams||{});
      o.features=Object.assign({},dm._lastFeatures||{});
      if(theme){
        o.theme={name:theme.trackTheme?theme.trackTheme.name:null,biome:theme.biome,
          timeT:+theme.timeT.toFixed(3),night:isNight(),skyHue:theme.skyHue,
          clouds:theme.clouds,rain:theme.rain,wet:!!theme.wet,snow:!!theme.snow,
          storm:+(theme.storm||0).toFixed(2),lensFlare:+(theme.lensFlare||0).toFixed(2),
          aurora:!!theme.aurora,auroraHue:theme.auroraHue,auroraShape:theme.auroraShape,
          heavyFog:theme.heavyFog?{density:+theme.heavyFog.density.toFixed(2),
            hue:theme.heavyFog.hue,reach:+theme.heavyFog.reach.toFixed(2)}:null,
          geoTheme:!!theme.geoTheme};
        o.zones=(theme.zones||[]).map(z=>({at:+z.at.toFixed(2),hue:z.hue,sat:z.sat,
          lumA:z.lumA,lumB:z.lumB,backdrop:z.backdrop,
          vegDens:+z.vegDens.toFixed(2),vegHue:z.vegHue,propMix:+z.propMix.toFixed(2)}));
      }
      o.effects={roadFire:!!dm._roadFire,fireWater:!!dm._fireWater,firePat:dm._firePat,
        fireCover:dm._fireCover,fireSide:dm._fireSide,fireScale:dm._fireScale,
        inferno:!!dm._inferno,rasterWater:!!dm._rasterWater,rasterAlgo:dm._rasterAlgo,
        signTrack:!!dm._signTrackFlag,smokeNow:+(dm._smokeNow||0).toFixed(2),
        spectacle:dm._spectacle||null,weather:dm._weather||null,
        barren:!!dm._barrenFlag};
      o.bldJsDrawn=dm._bldJsDrawn||0;
    }catch(e){o.error=e.message;}
    return o;
  }};
