function bcRender(list){
  const body=document.getElementById('_bc_body');if(!body)return;
  const _glf="'Germania One',serif";
  let h='<div style="text-align:center;margin-bottom:14px">'+
    '<div style="color:#ffd23a;font-size:30px;letter-spacing:4px;font-family:'+_glf+';'+
    'text-shadow:0 0 22px rgba(255,210,58,0.4)">BEST COURSES</div>'+
    '<div style="color:#8fd6ff;font-size:12px;margin-top:4px">'+
    (list.length?((bcSel+1)+' / '+list.length+' \u00b7 D-PAD \u2190\u2192 browse \u00b7 A race \u00b7 X remove \u00b7 B back')
                :'No courses committed yet \u00b7 B back')+'</div></div>';
  if(!list.length){
    h+='<div style="color:#5f9ec0;text-align:center;font-size:13px;line-height:1.7;'+
      'border:1px dashed #2f4a6a;border-radius:8px;padding:26px">'+
      'Race a generated track you enjoy, then choose<br>'+
      '<span style="color:#a6ffc8">COMMIT TO BEST COURSES</span> from the pause menu.<br>'+
      'It will be saved here permanently.</div>';
    body.innerHTML=h;return;
  }
  const e=list[bcSel];
  const feats=e.features||{};
  let frows='';
  for(const k of _SR_FEAT_ORDER){const n=feats[k];
    if(n>0)frows+='<li style="margin:2px 0">'+n+'\u00d7 '+_SR_FEAT_LABELS[k]+'</li>';}
  if(!frows)frows='<li style="color:#8fa;opacity:0.7">Classic circuit</li>';
  h+='<div style="border:2px solid #5fcf8a;border-radius:10px;background:#050510;padding:16px;'+
    'box-shadow:0 0 28px rgba(140,255,180,0.25)">'+
    '<div style="display:flex;gap:16px;align-items:flex-start;flex-wrap:wrap">'+
      // LEFT: start-line preview + minimap
      '<div style="flex:0 0 300px">'+
        '<div style="color:#a6ffc8;font-size:10px;letter-spacing:1px;margin-bottom:3px">STARTING LINE</div>'+
        '<canvas id="_bc_start" width="300" height="150" style="width:300px;height:150px;'+
          'border:1px solid #2f7a4f;border-radius:5px;background:#02030a;display:block"></canvas>'+
        '<div style="color:#a6ffc8;font-size:10px;letter-spacing:1px;margin:8px 0 3px">TRACK MAP</div>'+
        '<canvas id="_bc_map" width="300" height="150" style="width:300px;height:150px;'+
          'border:1px solid #2f7a4f;border-radius:5px;background:#02030a;display:block"></canvas>'+
      '</div>'+
      // RIGHT: details
      '<div style="flex:1;min-width:220px">'+
        '<div style="color:#cfe8ff;font-size:20px;margin-bottom:2px">'+(e.name||'COURSE')+'</div>'+
        '<div style="color:#5f9ec0;font-size:11px;margin-bottom:10px">'+
          (e.themeName||'')+(e.arch?' \u00b7 '+e.arch:'')+
          (e.isLong?' \u00b7 <span style="color:#ffd23a">\u2605 EXTENDED</span>':'')+'</div>'+
        '<div style="color:#a6ffc8;font-size:11px;font-weight:bold;letter-spacing:1px;margin-bottom:3px">TRACK FEATURES</div>'+
        '<ul style="margin:0 0 10px;padding-left:16px;color:#cfe8ff;font-size:11px;line-height:1.4">'+frows+'</ul>'+
        '<div style="color:#5f9ec0;font-size:10px">Length: '+(e.segs||0)+' segments'+
          ' \u00b7 Seed '+e.seed+'</div>'+
      '</div>'+
    '</div></div>';
  body.innerHTML=h;
  // minimap
  const mc=document.getElementById('_bc_map');
  if(mc&&e.pts&&e.pts.length){
    const c2=mc.getContext('2d');
    c2.strokeStyle='#9fe8ff';c2.lineWidth=2;c2.beginPath();
    e.pts.forEach(([x,y],i)=>{const px=14+x*272,py=10+y*130;i===0?c2.moveTo(px,py):c2.lineTo(px,py);});
    c2.closePath();c2.stroke();
    // start marker
    if(e.pts[0]){const[sx,sy]=e.pts[0];
      c2.fillStyle='#ffd23a';c2.beginPath();c2.arc(14+sx*272,10+sy*130,4,0,Math.PI*2);c2.fill();}
  }
  bcDrawStartPreview(e);
}

function bcDrawStartPreview(e){
  const cv=document.getElementById('_bc_start');if(!cv)return;
  const c=cv.getContext('2d');const W=300,H=150;
  const TT=(typeof TRACK_THEMES!=='undefined'&&TRACK_THEMES)
    ?TRACK_THEMES.find(t=>t&&t.name===e.themeName)||TRACK_THEMES.find((_,i)=>i===e.seed%TRACK_THEMES.length)
    :null;
  const skyA=TT?TT.skyA:'#0a1030', skyB=TT?TT.skyB:'#243a6a';
  const roadA=TT?TT.roadA:'#2a2a34', roadB=TT?TT.roadB:'#33333f';
  const railL=TT?TT.railL:'#ff4d6d', railR=TT?TT.railR:'#4dd2ff';
  // sky
  const gsky=c.createLinearGradient(0,0,0,H*0.55);
  gsky.addColorStop(0,skyA);gsky.addColorStop(1,skyB);
  c.fillStyle=gsky;c.fillRect(0,0,W,H*0.55);
  // ground
  const gg=c.createLinearGradient(0,H*0.55,0,H);
  gg.addColorStop(0,TT?TT.floorA:'#0d1a12');gg.addColorStop(1,TT?TT.floorB:'#060d09');
  c.fillStyle=gg;c.fillRect(0,H*0.55,W,H*0.45);
  // road trapezoid receding to a vanishing point
  const vpX=W/2, vpY=H*0.55;
  c.fillStyle=roadB;
  c.beginPath();c.moveTo(W*0.10,H);c.lineTo(W*0.90,H);
  c.lineTo(vpX+W*0.035,vpY);c.lineTo(vpX-W*0.035,vpY);c.closePath();c.fill();
  // alternating rumble bands for depth
  for(let i=0;i<7;i++){
    const t0=i/7,t1=(i+0.5)/7;
    const y0=H-(H-vpY)*t0, y1=H-(H-vpY)*t1;
    const w0=(W*0.40)*(1-t0)+W*0.035, w1=(W*0.40)*(1-t1)+W*0.035;
    c.fillStyle=(i&1)?roadA:roadB;
    c.beginPath();c.moveTo(vpX-w0,y0);c.lineTo(vpX+w0,y0);
    c.lineTo(vpX+w1,y1);c.lineTo(vpX-w1,y1);c.closePath();c.fill();
  }
  // rails
  c.strokeStyle=railL;c.lineWidth=2;
  c.beginPath();c.moveTo(W*0.10,H);c.lineTo(vpX-W*0.035,vpY);c.stroke();
  c.strokeStyle=railR;
  c.beginPath();c.moveTo(W*0.90,H);c.lineTo(vpX+W*0.035,vpY);c.stroke();
  // start/finish gantry line
  c.fillStyle='#ffffff';
  for(let i=0;i<12;i++){
    const bw=(W*0.62)/12, bx=vpX-W*0.31+i*bw;
    if(i&1)c.fillRect(bx,H*0.80,bw,5);
  }
  // grid of machines ready to start (2 columns, staggered)
  const cols=['#39ff14','#ff4d6d','#4dd2ff','#ffd23a','#c77dff','#ff9a1f'];
  for(let r=0;r<3;r++)for(let cI=0;cI<2;cI++){
    const t0=0.10+r*0.11;
    const y=H-(H-vpY)*t0;
    const sc=1-t0*0.75;
    const halfW=(W*0.40)*(1-t0)+W*0.035;
    const x=vpX+(cI?1:-1)*halfW*0.45;
    const mw=16*sc, mh=8*sc;
    c.fillStyle=cols[(r*2+cI)%cols.length];
    c.beginPath();c.moveTo(x,y-mh);c.lineTo(x-mw/2,y);c.lineTo(x+mw/2,y);c.closePath();c.fill();
    c.fillStyle='rgba(255,255,255,0.35)';
    c.fillRect(x-mw*0.18,y-mh*0.7,mw*0.36,mh*0.3);
  }
  // label
  c.fillStyle='rgba(255,255,255,0.85)';c.font='bold 9px monospace';c.textAlign='center';
  c.fillText('READY',W/2,H*0.93);
}

function bcOpen(){
  _hideWeatherLayers();
  const list=bcLoad();
  let ov=document.getElementById('_bc_menu');if(ov)ov.remove();
  try{document.querySelectorAll('.stream-container,.scroll-up-image').forEach(el=>{el._bcPrev=el.style.display;el.style.display='none';});}catch(e){}
  ov=document.createElement('div');ov.id='_bc_menu';
  /* (item 18) Styling lives in race.css under #_bc_menu. */
  ov.innerHTML='<div id="_bc_body"></div>';
  document.body.appendChild(ov);
  bcSel=0;bcRender(list);
  musicSit('title');
  let prev={L:true,R:true,A:true,B:true,X:true},held={L:0,R:0};
  const RD=350,RR=140;
  bcPollIv=setInterval(()=>{
    if(!document.getElementById('_bc_menu')){clearInterval(bcPollIv);return;}
    const pads=navigator.getGamepads?navigator.getGamepads():[];
    let L=false,R=false,A=false,B=false,X=false;
    for(const pd of pads){if(!pd)continue;
      L=L||!!pd.buttons[14]?.pressed;R=R||!!pd.buttons[15]?.pressed;
      A=A||!!pd.buttons[0]?.pressed;B=B||!!pd.buttons[1]?.pressed;
      X=X||!!pd.buttons[2]?.pressed;}
    const cur=bcLoad(),n=Math.max(cur.length,1);
    const t2=performance.now();let moved=false;
    const dir=(p,k,fn)=>{if(p){if(!prev[k]){fn();moved=true;held[k]=t2+RD;}
      else if(t2>=held[k]){fn();moved=true;held[k]=t2+RR;}}else held[k]=0;};
    dir(L,'L',()=>bcSel=(bcSel+n-1)%n);
    dir(R,'R',()=>bcSel=(bcSel+1)%n);
    if(moved)bcRender(cur);
    if(A&&!prev.A){const e=cur[bcSel];if(e){
      /* The entry's own generator settings MUST be applied, and the stale
         World-Tour state cleared, or buildTrack() produces a different track
         from the one the tile previewed. */
      try{ dm._algoOverride=e.algo||null; }catch(e2){}
      try{ dm._wtSettlement=null; dm._wtRace=null; }catch(e2){}
      try{ if(window.ZS_stopDemoTimers)window.ZS_stopDemoTimers(); }catch(e2){}
      bcClose();
      start(e.seed,{fromSR:true,tod:e.tod,fv:e.fv});
      try{ dm._wtSettlement=null; dm._wtRace=null; }catch(e2){}
      try{
        var _bt=document.getElementById('scr-title');
        if(_bt){_bt.style.zIndex='';_bt.classList.remove('active');}
        var _bv=document.getElementById('title-veil');
        if(_bv)_bv.style.display='none';
        document.body.classList.add('in-race');
        document.body.classList.remove('on-title');
      }catch(e2){}
    }}
    if(X&&!prev.X){const e=cur[bcSel];if(e){                    // X = delete
      cur.splice(bcSel,1);bcStore(cur);
      if(bcSel>=cur.length)bcSel=Math.max(0,cur.length-1);
      bcRender(cur);}}
    if(B&&!prev.B)bcClose();
    prev={L,R,A,B,X};
  },50);
}

function bcClose(){
  const ov=document.getElementById('_bc_menu');if(ov)ov.remove();
  if(bcPollIv)clearInterval(bcPollIv);
  try{document.querySelectorAll('.stream-container,.scroll-up-image').forEach(el=>{if(el._bcPrev!=null)el.style.display=el._bcPrev;});}catch(e){}
}

function _srFeatureListHTML(e){
  const f=e&&e.features;
  let rows='';
  if(f){
    for(const k of _SR_FEAT_ORDER){
      const n=f[k];
      if(n>0)rows+='<div style="margin:1px 0">'+n+'\u00d7 '+_SR_FEAT_LABELS[k]+'</div>';
    }
  }
  if(!rows)rows='<div style="color:#8fa;opacity:0.7">Classic circuit</div>';
  const longTag=e&&e.isLong?'<div style="color:#ffd23a;font-size:9.5px;margin-bottom:3px;font-weight:bold">\u2605 EXTENDED +30% LENGTH</div>':'';
  const badges=
    (e&&e.roadFire?'<div style="color:#ff9a3c;font-size:9.5px;margin-bottom:2px;font-weight:bold">\ud83d\udd25 FIRE HAZARD</div>':'')+
    (e&&e.hasWater?'<div style="color:#5fd8ff;font-size:9.5px;margin-bottom:2px;font-weight:bold">\ud83c\udf0a WATERSIDE RUN</div>':'');
  return '<div style="width:100%">'+longTag+badges+
    '<div style="color:#cfe8ff;font-size:10.5px;line-height:1.55">'+rows+'</div></div>';
}

