// Feature-count overrides — applied to the manifest when an algo override is active
function _algoApplyFeatCounts(overrides){
  if(!overrides)return;
  const featMap={
    '_feat_corkscrew':'corkscrew','_feat_pipe':'pipe','_feat_tunnel':'tunnel',
    '_feat_halfpipe':'halfpipe','_feat_wallride':'wallride',
    '_feat_verticalloop':'verticalloop','_feat_airgap':'airgap',
    '_feat_split':'split','_feat_bridge':'bridge','_feat_underpass':'underpass',
    '_feat_plunge':'plunge','_feat_climb':'climb','_feat_rush':'rush',
    '_feat_hairpin':'hairpin','_feat_gauntlet':'gauntlet','_feat_bowl':'bowl',
    '_feat_sideways':'sideways',
    '_feat_hyperlane':'hyperlane','_feat_junction':'junction',
    '_feat_phase':'phase','_feat_mesh':'mesh','_feat_slalom':'slalom',
    '_feat_narrows':'narrows','_feat_bottleneck':'bottleneck','_feat_multideck':'multideck',
  };
  for(const ok in featMap){
    if(overrides[ok]!=null&&typeof _FEAT==='object'&&_FEAT[featMap[ok]]){
      _FEAT[featMap[ok]][0]=+overrides[ok];
    }
  }
}
let _algoModal=null,_algoTab='best',_algoFocus=0,_algoCfg={},_algoPadDebounce=0;
function _algoLoadConfigs(){
  try{const raw=localStorage.getItem('zs_algo_configs');return raw?JSON.parse(raw):{};}
  catch(e){return {};}
}
function _algoSaveConfigs(o){
  try{localStorage.setItem('zs_algo_configs',JSON.stringify(o));}catch(e){}
}
