      const ang=(x,y)=>{let d=Math.atan2(-y,x)*180/Math.PI;if(d<0)d+=360;return d.toFixed(0);};
      const lx=p.axes[0]||0,ly=p.axes[1]||0,rx=p.axes[2]||0,ry=p.axes[3]||0;
